BEGIN
    FOR spec IN SELECT value FROM jsonb_array_elements($data_08c56b4e8251$[{"table":"drugs","id":"3cb970b7-e7a9-4d96-8658-a4b6a4ae9368","guard":{"slug":"digoxin"},"edits":[{"path":["adult_bolus_dose"],"before":"Rapid digitalisation (oral/IV): 0.75-1.5 mg total, in divided doses over 24 hours. E.g., 0.75-1 mg initially, then 0.25-0.5 mg 6-8 hourly. Max 1 mg within 24 hours.\nSlow digitalisation (oral): 62.5–250 micrograms daily, titrated to effect.","after":"Rapid IV loading with digoxin injection, adults: 500–1,000 micrograms TOTAL depending on age, lean body weight, renal function and recent glycoside exposure. Give about half first, then reassess before each remaining fraction at 4–8 hour intervals. Infuse each dose over 10–20 minutes.\nRapid oral loading with the named tablets, where appropriate: 750–1,500 micrograms total. In those with greater toxicity risk or less urgency divide the dose, about half first and remaining fractions at 6-hour intervals after reassessment.\nSlow oral loading in selected adults with the named tablets: 250–750 micrograms daily for one week, then an individualised maintenance dose. Reduce or reconsider loading when a cardiac glycoside was taken in the preceding two weeks.","sources":["https://www.medicines.org.uk/emc/product/5462/smpc","https://www.medicines.org.uk/emc/product/5465/smpc"]},{"path":["dosing"],"before":"Adult maintenance (oral): 62.5–500 micrograms daily (typical 125–250 micrograms daily). Adjust for age, weight, renal function.\nPaediatric IV loading doses for rapid digitalisation (oral dose approx. 20-33% higher):\n• Preterm neonates (<1.5 kg): 25 micrograms/kg over 24 hours.\n• Preterm neonates (1.5-2 kg): 30 micrograms/kg over 24 hours.\n• Term neonates: 35 micrograms/kg over 24 hours.\n• 1 month–2 years: 45 micrograms/kg over 24 hours.\n• 2–5 years: 35 micrograms/kg over 24 hours.\n• 5–10 years: 25 micrograms/kg over 24 hours (max. total 750 micrograms).\n(Loading dose to be given over 24 hours: 50% initial, then 25% after 8 hours, then remaining 25% after a further 8 hours, each IV dose over 10-20 minutes).\nPaediatric maintenance: 25-30% of individual loading dose daily, in 1-2 divided doses.","after":"Adult maintenance (oral): 62.5–500 micrograms daily (typical 125–250 micrograms daily). Adjust for age, weight, renal function.\nPaediatric IV loading, named 250 micrograms/mL product. Total over 24 hours: preterm neonates under 1.5 kg, 20 micrograms/kg; preterm neonates 1.5–2.5 kg, 30 micrograms/kg; term neonates through 2 years, 35 micrograms/kg; 2–5 years, 35 micrograms/kg; 5–10 years, 25 micrograms/kg. Give about half the total first. Reassess before giving further fractions at intervals of 4–8 hours. Infuse each dose over 10–20 minutes. Review recent glycoside exposure, renal function and clinical response.\nInitial daily maintenance for the named product: preterm neonates, 20% of the 24-hour loading dose; term neonates and children up to 10 years, 25%. Individualise using clinical and serum monitoring.","sources":["https://www.medicines.org.uk/emc/product/5462/smpc"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Digoxin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=digoxin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Digoxin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=digoxin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Digoxin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=digoxin"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Digoxin 250 microgram/ml solution for injection/infusion — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/5462/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Digoxin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=digoxin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Digoxin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=digoxin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Digoxin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=digoxin"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Digoxin 250 microgram/ml solution for injection/infusion — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/5462/smpc"},{"title":"Digoxin 0.25 mg tablets, UK SmPC, section 4.2","publisher":"electronic Medicines Compendium","accessed":"2026-11-19","url":"https://www.medicines.org.uk/emc/product/5465/smpc"}],"sources":["https://www.medicines.org.uk/emc/product/5462/smpc","https://www.medicines.org.uk/emc/product/5465/smpc"]}]},{"table":"drugs","id":"66ed78ea-2f4e-4c54-bfae-221250a629ec","guard":{"slug":"prilocaine"},"edits":[{"path":["adult_bolus_dose"],"before":"• Infiltration/Nerve block: Max 6 mg/kg (up to 400 mg); with felypressin max 8 mg/kg (up to 600 mg).\n• Adult distal-forearm IVRA (RCEM): 3 mg/kg preservative-free plain prilocaine, diluted to 0.5% as required. This is a separate regimen from infiltration/nerve-block maxima; follow the full tourniquet and monitoring protocol.","after":"• Infiltration/Nerve block: Max 6 mg/kg (up to 400 mg).\n• UK Citanest 3% with Octapressin, for dental infiltration or dental nerve block in healthy adults: usually 1–5 mL. Maximum 10 mL (300 mg prilocaine at 30 mg/mL).\n• Adult distal-forearm IVRA (RCEM): 3 mg/kg preservative-free plain prilocaine, diluted to 0.5% as required. This is a separate regimen from infiltration/nerve-block maxima; follow the full tourniquet and monitoring protocol.","sources":["https://www.dentsplysirona.com/content/dam/dentsply/pim/manufacturer/Preventive/Anesthesia/Injectable_Anesthesia/Citanest_3_with_Octapressin_Injectable_Anaesthetic/UK%20Ctanest%20SPC%20SEP2016.pdf"]},{"path":["dosing"],"before":"• Adults (Injection):\n  • Max single dose without felypressin: 6 mg/kg (up to 400 mg).\n  • Max single dose with felypressin: 8 mg/kg (up to 600 mg).\n• Paediatric (Injection):\n  • Not recommended in infants <6 months.\n  • Children >6 months, Aspen 1% injection: up to 5 mg/kg for infiltration/nerve block; use the lowest effective dose. The preserved multidose formulation is unsuitable for intrathecal/epidural, intraocular/retrobulbar administration, or other blocks requiring more than 15 mL; do not treat the weight-based ceiling as overriding these restrictions.\n• Elderly/Hepatic/Renal Impairment: Dose reduction may be required; titrate carefully.\n• Topical (EMLA cream/patch - intact skin):\n  • Term infants 0–2 months: up to 1 g on 10 cm² for 1 hour, once only in 24 hours. Do not apply for 4 hours.\n  • Infants 3–11 months: up to 2 g on 20 cm² for 1 hour. From age 3 months, at most two doses separated by at least 12 hours may be used in 24 hours under the product instructions.\n  • Children 1-5 years (10-20 kg): Max 10 g (approx 100 cm²) for 1-5 hours.\n  • Children 6-11 years (>20 kg): Max 20 g (approx 200 cm²) for 1-5 hours.\n  • Adults: Apply 1.5 g/10 cm² up to max 60 g/600 cm² for minimum 1 hour, maximum 5 hours.","after":"• Adults (Injection):\n  • Max single dose without felypressin: 6 mg/kg (up to 400 mg).\n  • UK Citanest 3% with Octapressin, for dental infiltration or dental nerve block in healthy adults: usually 1–5 mL. Maximum 10 mL (300 mg prilocaine at 30 mg/mL).\n• Paediatric (Injection):\n  • Not recommended in infants <6 months.\n  • Children >6 months, Aspen 1% injection: up to 5 mg/kg for infiltration/nerve block; use the lowest effective dose. The preserved multidose formulation is unsuitable for intrathecal/epidural, intraocular/retrobulbar administration, or other blocks requiring more than 15 mL; do not treat the weight-based ceiling as overriding these restrictions.\n• Elderly/Hepatic/Renal Impairment: Dose reduction may be required; titrate carefully.\n• Topical (EMLA cream/patch - intact skin):\n  • Term infants 0–2 months: up to 1 g on 10 cm² for 1 hour, once only in 24 hours. Do not apply for 4 hours.\n  • Infants 3–11 months: up to 2 g on 20 cm² for 1 hour. From age 3 months, at most two doses separated by at least 12 hours may be used in 24 hours under the product instructions.\n  • Children 1-5 years (10-20 kg): Max 10 g (approx 100 cm²) for 1-5 hours.\n  • Children 6-11 years (>20 kg): Max 20 g (approx 200 cm²) for 1-5 hours.\n  • Adults: Apply 1.5 g/10 cm² up to max 60 g/600 cm² for minimum 1 hour, maximum 5 hours.","sources":["https://www.dentsplysirona.com/content/dam/dentsply/pim/manufacturer/Preventive/Anesthesia/Injectable_Anesthesia/Citanest_3_with_Octapressin_Injectable_Anaesthetic/UK%20Ctanest%20SPC%20SEP2016.pdf"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Prilocaine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=prilocaine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Prilocaine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=prilocaine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Prilocaine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=prilocaine"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Management of Severe Local Anaesthetic Toxicity (Safety Guideline)","url":"https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-toxicity"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Prilocaine — targeted dosing/safety source (4.2–4.4; updated2026-06-12)","url":"https://www.medicines.org.uk/emc/product/871/smpc"},{"accessed":"2026-10-30","publisher":"Primary or official clinical source","title":"Prilocaine — targeted source: RCEM adult distal-forearm IVRA, revised November 2017; pp 3–4","url":"https://rcem.ac.uk/wp-content/uploads/2024/04/Intravenous_Regional_Anaesthesia_for_Distal_Forearm_Fractures_Biers_Block_v1.pdf"},{"accessed":"2026-10-30","publisher":"Primary or official clinical source","title":"Prilocaine — targeted source: Aspen 1% injection SmPC 4.2; updated 2022-07-14","url":"https://www.medicines.org.uk/emc/product/870/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Prilocaine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=prilocaine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Prilocaine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=prilocaine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Prilocaine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=prilocaine"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Management of Severe Local Anaesthetic Toxicity (Safety Guideline)","url":"https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-toxicity"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Prilocaine — targeted dosing/safety source (4.2–4.4; updated2026-06-12)","url":"https://www.medicines.org.uk/emc/product/871/smpc"},{"accessed":"2026-10-30","publisher":"Primary or official clinical source","title":"Prilocaine — targeted source: RCEM adult distal-forearm IVRA, revised November 2017; pp 3–4","url":"https://rcem.ac.uk/wp-content/uploads/2024/04/Intravenous_Regional_Anaesthesia_for_Distal_Forearm_Fractures_Biers_Block_v1.pdf"},{"accessed":"2026-10-30","publisher":"Primary or official clinical source","title":"Prilocaine — targeted source: Aspen 1% injection SmPC 4.2; updated 2022-07-14","url":"https://www.medicines.org.uk/emc/product/870/smpc"},{"title":"Citanest with Octapressin Dental, UK SmPC, section 4.2","publisher":"Dentsply Sirona","accessed":"2026-11-19","url":"https://www.dentsplysirona.com/content/dam/dentsply/pim/manufacturer/Preventive/Anesthesia/Injectable_Anesthesia/Citanest_3_with_Octapressin_Injectable_Anaesthetic/UK%20Ctanest%20SPC%20SEP2016.pdf"}],"sources":["https://www.dentsplysirona.com/content/dam/dentsply/pim/manufacturer/Preventive/Anesthesia/Injectable_Anesthesia/Citanest_3_with_Octapressin_Injectable_Anaesthetic/UK%20Ctanest%20SPC%20SEP2016.pdf"]}]},{"table":"drugs","id":"6f0db488-a42c-4fde-b14b-76dd48ad9a56","guard":{"slug":"levobupivacaine"},"edits":[{"path":["adult_bolus_dose"],"before":"• Surgical anaesthesia (epidural): 75–150 mg (e.g. 15–30 mL of 5 mg/mL solution). Max 150 mg single dose. (anaesthetic practice)\n• Peripheral nerve block: 25–150 mg depending on site and volume. Max 150 mg single dose.\n• Spinal anaesthesia: 10–20 mg (2–4 mL of 5 mg/mL solution).","after":"• Surgical anaesthesia (epidural): 75–150 mg (e.g. 15–30 mL of 5 mg/mL solution). Max 150 mg single dose. (anaesthetic practice)\n• Peripheral nerve block: 25–150 mg depending on site and volume. Max 150 mg single dose.\n• Adult intrathecal surgical anaesthesia: the named 5 mg/mL UK SmPC dosing table specifies 3 mL (15 mg). Follow the product and route-specific dosing schedule.","sources":["https://www.medicines.org.uk/emc/product/13644/smpc"]},{"path":["dosing"],"before":"• Adults: Max single dose 150 mg. Max 24-hour dose 400 mg. Doses should be adjusted according to site of administration and patient factors.\n• Labour analgesia (epidural bolus): typically 6–10 mL of 1.25 mg/mL or 2.5 mg/mL.\n• Caudal epidural (adult): up to 100 mg of 2.5 mg/mL (40 mL).\n• Paediatrics: the cited licensed 1.25 mg/kg per side regimen is for ilioinguinal/iliohypogastric block, not a generic caudal dose. Paediatric caudal/continuous epidural use requires a named specialist age/route protocol. Do not combine 0.25 mg/kg/hour with a claimed 3 mg/kg/day maximum: 24 hours at that rate gives 6 mg/kg.","after":"• Adults: Max single dose 150 mg. Max 24-hour dose 400 mg. Doses should be adjusted according to site of administration and patient factors.\n• Labour epidural bolus in the named UK SmPC: 6–10 mL of 2.5 mg/mL (15–25 mg). Continuous labour epidural analgesia uses the separate infusion schedule and concentration.\n• Caudal epidural (adult): up to 100 mg of 2.5 mg/mL (40 mL).\n• Paediatrics: the cited licensed 1.25 mg/kg per side regimen is for ilioinguinal/iliohypogastric block, not a generic caudal dose. Paediatric caudal/continuous epidural use requires a named specialist age/route protocol. Do not combine 0.25 mg/kg/hour with a claimed 3 mg/kg/day maximum: 24 hours at that rate gives 6 mg/kg.","sources":["https://www.medicines.org.uk/emc/product/13644/smpc"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Levobupivacaine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Levobupivacaine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Levobupivacaine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Management of Severe Local Anaesthetic Toxicity (Safety Guideline)","url":"https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-toxicity"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Levobupivacaine — targeted dosing/safety source (4.2; updated2026-08-19)","url":"https://www.medicines.org.uk/emc/product/13641/smpc"},{"accessed":"2026-10-30","publisher":"assets.hpra.ie","title":"Levobupivacaine — targeted dosing/safety source (4.2 paediatric licensed block)","url":"https://assets.hpra.ie/products/Human/30235/Licence_PA2059-009-005_18052021115309.pdf"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Levobupivacaine — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Levobupivacaine — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Levobupivacaine — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=levobupivacaine"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Management of Severe Local Anaesthetic Toxicity (Safety Guideline)","url":"https://anaesthetists.org/Home/Resources-publications/Guidelines/Management-of-severe-local-anaesthetic-toxicity"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Levobupivacaine — targeted dosing/safety source (4.2; updated2026-08-19)","url":"https://www.medicines.org.uk/emc/product/13641/smpc"},{"accessed":"2026-10-30","publisher":"assets.hpra.ie","title":"Levobupivacaine — targeted dosing/safety source (4.2 paediatric licensed block)","url":"https://assets.hpra.ie/products/Human/30235/Licence_PA2059-009-005_18052021115309.pdf"},{"title":"Levobupivacaine 5 mg/mL injection/infusion, UK SmPC, section 4.2","publisher":"electronic Medicines Compendium","accessed":"2026-11-19","url":"https://www.medicines.org.uk/emc/product/13644/smpc"}],"sources":["https://www.medicines.org.uk/emc/product/13644/smpc"]}]},{"table":"drugs","id":"74158d0d-bc89-4263-80d5-345c27b65114","guard":{"slug":"methylprednisolone"},"edits":[{"path":["adult_bolus_dose"],"before":"• Acute severe asthma: 40 mg IV.\n• Anaphylaxis: 40 mg IV (adjunct after adrenaline).\n• Acute exacerbation of multiple sclerosis: 500 mg to 1 g IV daily for 3-5 days (BNF suggests 160 mg daily for 7 days then 64 mg every other day for 3 weeks, tapering).","after":"• Acute severe asthma: 40 mg IV.\n• Anaphylaxis: routine corticosteroids have no role in initial resuscitation. Give adrenaline and fluid according to the appropriate pathway. In refractory perioperative reactions or shock the specialist team may consider steroids.\n• Relapse of multiple sclerosis requiring steroid treatment (NICE NG220): offer oral methylprednisolone 500 mg daily for 5 days. Consider IV methylprednisolone 1 g daily for 3–5 days if oral therapy has failed or is intolerable, or when admission is needed for a severe relapse or monitoring.","sources":["https://www.nice.org.uk/guidance/ng220/chapter/Recommendations","https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Methylprednisolone — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=methylprednisolone"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Methylprednisolone — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=methylprednisolone"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Methylprednisolone — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=methylprednisolone"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","revision":"09/2026","scope":"53mg methylprednisolone sodium succinate equivalent to40mg methylprednisolone/vial,IV/IM after reconstitution;adult/paediatric scope,other strengths and acetate excluded.","sections":["1","2","3","4.1","4.2"],"title":"Solu-Medrone 40 mg Powder for Solution for Injection — product SPC","url":"https://www.medicines.org.uk/emc/product/1550/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Methylprednisolone — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=methylprednisolone"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Methylprednisolone — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=methylprednisolone"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Methylprednisolone — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=methylprednisolone"},{"accessed":"2026-11-01","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Selected formulation, route and population only. Other presentations, storage and treatment doses are not verified; no current stock availability certification.","revision":"09/2026","scope":"53mg methylprednisolone sodium succinate equivalent to40mg methylprednisolone/vial,IV/IM after reconstitution;adult/paediatric scope,other strengths and acetate excluded.","sections":["1","2","3","4.1","4.2"],"title":"Solu-Medrone 40 mg Powder for Solution for Injection — product SPC","url":"https://www.medicines.org.uk/emc/product/1550/smpc"},{"title":"Multiple sclerosis in adults, NG220, relapse treatment","publisher":"NICE","accessed":"2026-11-19","url":"https://www.nice.org.uk/guidance/ng220/chapter/Recommendations"},{"title":"Peri-operative anaphylaxis algorithm for anaesthetists and intensivists","publisher":"Resuscitation Council UK","accessed":"2026-11-19","url":"https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"}],"sources":["https://www.nice.org.uk/guidance/ng220/chapter/Recommendations","https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]}]},{"table":"drugs","id":"8549eadf-6e1a-4dff-902a-73bfd06e06a2","guard":{"slug":"suxamethonium"},"edits":[{"path":["pharmacokinetics"],"before":"• Onset: 30–60 seconds after IV administration.\n• Duration: 2–6 minutes (IV). Up to 10 minutes with abnormal plasma cholinesterase.\n• Metabolism: Rapidly hydrolysed in plasma by plasma cholinesterase to succinylmonocholine (weakly active); then to choline and succinic acid.\n• Excretion: Minimal renal excretion of unchanged drug.\n• Prolonged action: Due to genetic variants of plasma cholinesterase, or acquired deficiency (e.g., severe liver disease, major burns >24 hours, severe crush injury >5 days, extensive soft tissue trauma, denervation injuries, rhabdomyolysis, severe sepsis, spinal cord injury, organophosphate poisoning, some systemic conditions, antineoplastic drugs, pregnancy).","after":"• Onset: 30–60 seconds after IV administration.\n• Duration: 2–6 minutes (IV). Marked inherited butyrylcholinesterase deficiency can prolong paralysis for hours. Maintain sedation and ventilatory support with quantitative neuromuscular monitoring until recovery permits safe extubation.\n• Metabolism: Rapidly hydrolysed in plasma by plasma cholinesterase to succinylmonocholine (weakly active); then to choline and succinic acid.\n• Excretion: Minimal renal excretion of unchanged drug.\n• Prolonged action: Due to genetic variants of plasma cholinesterase, or acquired deficiency (e.g., severe liver disease, major burns >24 hours, severe crush injury >5 days, extensive soft tissue trauma, denervation injuries, rhabdomyolysis, severe sepsis, spinal cord injury, organophosphate poisoning, some systemic conditions, antineoplastic drugs, pregnancy).","sources":["https://www.orphananesthesia.eu/rare-diseases/published-guidelines/pseudocholinesterase-deficiency/1793-pseudocholinesterase-deficiency-1/file.html"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Suxamethonium (succinylcholine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Suxamethonium (succinylcholine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Suxamethonium (succinylcholine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Suxamethonium Chloride 50mg/ml Solution for Injection/Infusion — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/3401/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Suxamethonium (succinylcholine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Suxamethonium (succinylcholine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Suxamethonium (succinylcholine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=suxamethonium"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Suxamethonium Chloride 50mg/ml Solution for Injection/Infusion — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/3401/smpc"},{"title":"Anaesthesia recommendations for pseudocholinesterase deficiency","publisher":"OrphanAnaesthesia","accessed":"2026-11-19","url":"https://www.orphananesthesia.eu/rare-diseases/published-guidelines/pseudocholinesterase-deficiency/1793-pseudocholinesterase-deficiency-1/file.html"}],"sources":["https://www.orphananesthesia.eu/rare-diseases/published-guidelines/pseudocholinesterase-deficiency/1793-pseudocholinesterase-deficiency-1/file.html"]}]},{"table":"drugs","id":"87ca9ddf-eddf-4f72-b5ca-bccf2b3de7ab","guard":{"slug":"nitrous-oxide"},"edits":[{"path":["presentation"],"before":"• Compressed gas, stored as a liquid (100% N2O in blue cylinders, Entonox 50% N2O / 50% O2 in blue/white cylinders).","after":"Pure medical nitrous oxide is supplied as a liquefied medicinal gas. The UK cylinder shoulder is blue. Entonox is a separate compressed medicinal gas mixture containing 50% nitrous oxide and 50% oxygen, with a blue-and-white quartered shoulder. Identify the cylinder by its product label.","sources":["https://www.bocgases.co.uk/files/entonox_integral_valve_cylinder.pdf","https://www.boconline.co.uk/wcsstore/UK_BOC_Industrial_Ntl_Store/pdf/downloads/505550-Patient-Information-Leaflet-Nitrous-Oxide.pdf","https://www.contractsfinder.service.gov.uk/Notice/Attachment/d2f584c3-2419-4a12-a802-946cbeb4b892"]},{"path":["preparation"],"before":"• 100% N2O in blue cylinders (EN 960). Entonox (50% N2O / 50% O2) in blue/white cylinders (EN 13799).\n• Entonox cylinders must be stored horizontally at temperatures >-6°C for at least 24 hours before use. If stored below -6°C, cylinders should be warmed to above 10°C for at least 2 hours and inverted several times immediately before use.\n• N2O administration requires an anaesthetic machine with anti-hypoxic safety system (maintains inspired O2 ≥25% or 30% depending on machine and setting).\n• Entonox is self-administered via a demand valve.","after":"• For anaesthesia, deliver medical nitrous oxide with oxygen through an appropriate anaesthetic machine and monitor the inspired oxygen concentration.\n• Entonox is usually self-administered through a demand valve. Keep the cylinder above 10°C for at least 24 hours before use to ensure the gases are mixed. Cold exposure can separate the mixture.\n• Follow the BOC instructions for the exact cylinder size and valve. Store F-size and larger cylinders vertically. Only use a shorter remix procedure where the manufacturer explicitly permits it for that cylinder. For the integral-valve ED cylinder, BOC permits three inversions just before use once the cylinder has warmed to 10°C. This exception does not apply to the larger integral-valve EX cylinder.","sources":["https://www.bocgases.co.uk/files/entonox_integral_valve_cylinder.pdf","https://www.boconline.co.uk/wcsstore/UK_BOC_Industrial_Ntl_Store/pdf/downloads/505550-Patient-Information-Leaflet-Nitrous-Oxide.pdf","https://www.contractsfinder.service.gov.uk/Notice/Attachment/d2f584c3-2419-4a12-a802-946cbeb4b892"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Nitrous oxide — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Nitrous oxide — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Nitrous oxide — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Nitrous oxide — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Nitrous oxide — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Nitrous oxide — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=nitrous+oxide"},{"accessed":"2026-09-13","publisher":"Association of Anaesthetists","title":"Recommendations for standards of monitoring during anaesthesia and recovery 2021","url":"https://doi.org/10.1111/anae.15501"},{"title":"Medical Nitrous Oxide — package leaflet","url":"https://www.boconline.co.uk/wcsstore/UK_BOC_Industrial_Ntl_Store/pdf/downloads/505550-Patient-Information-Leaflet-Nitrous-Oxide.pdf","accessed":"2026-11-19","publisher":"BOC Healthcare"},{"title":"ENTONOX — Summary of Product Characteristics, sections 6.4 and 6.6","url":"https://www.contractsfinder.service.gov.uk/Notice/Attachment/d2f584c3-2419-4a12-a802-946cbeb4b892","accessed":"2026-11-19","publisher":"BOC Healthcare"},{"title":"ENTONOX integral-valve cylinders — ED and EX instructions","url":"https://www.bocgases.co.uk/files/entonox_integral_valve_cylinder.pdf","accessed":"2026-11-19","publisher":"BOC Healthcare"}],"sources":["https://www.bocgases.co.uk/files/entonox_integral_valve_cylinder.pdf","https://www.boconline.co.uk/wcsstore/UK_BOC_Industrial_Ntl_Store/pdf/downloads/505550-Patient-Information-Leaflet-Nitrous-Oxide.pdf","https://www.contractsfinder.service.gov.uk/Notice/Attachment/d2f584c3-2419-4a12-a802-946cbeb4b892"]}]},{"table":"drugs","id":"8c321ce8-de0e-4509-8ce6-0cf9ff0918b5","guard":{"slug":"lorazepam"},"edits":[{"path":["adult_bolus_dose"],"before":"• Status epilepticus: 4 mg IV slowly over 2–5 minutes, may repeat once after 10–20 minutes (max 8 mg in 24 hours). Max single dose 4 mg (BNF). AAGBI/RCoA guidance suggests 0.05 mg/kg (max 4 mg) for status epilepticus (anaesthetic practice).\n• Premedication (oral): 1 mg to 4 mg orally 90–120 minutes pre-op.\n• Premedication (IV, anaesthetic practice): 0.05 mg/kg IV (max 4 mg) 15–20 minutes pre-op.","after":"• Adult convulsive status epilepticus: follow the individual emergency plan where available. With immediate IV access and resuscitation facilities, give lorazepam 4 mg slowly IV. If seizures persist 5–10 minutes after the first benzodiazepine dose, give a second dose under the emergency algorithm, counting any doses already given. Proceed to second-line antiseizure treatment after two benzodiazepine doses (NICE NG217).\n• Premedication (oral): 1 mg to 4 mg orally 90–120 minutes pre-op.\n• Premedication (IV, anaesthetic practice): 0.05 mg/kg IV (max 4 mg) 15–20 minutes pre-op.","sources":["https://www.nice.org.uk/guidance/ng217/chapter/treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Lorazepam — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=lorazepam"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Lorazepam — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=lorazepam"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Lorazepam — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=lorazepam"},{"accessed":"2026-10-30","publisher":"www.resus.org.uk","title":"Lorazepam — targeted dosing/safety source (Convulsive status epilepticus algorithm)","url":"https://www.resus.org.uk/sites/default/files/2026-02/RCUK%20Paediatric%20emergency%20algorithms%20and%20resources%20Feb%2026%20V6.pdf"},{"accessed":"2026-10-30","publisher":"www.nice.org.uk","title":"Lorazepam — targeted dosing/safety source (7.1.8–7.1.9)","url":"https://www.nice.org.uk/guidance/ng217/chapter/7-Treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures"},{"accessed":"2026-10-30","publisher":"www.rightdecisions.scot.nhs.uk","title":"Lorazepam — targeted dosing/safety source (Adultstatuspathway)","url":"https://www.rightdecisions.scot.nhs.uk/nhs-borders-clinical-guidelines/drugs-and-therapeutics/in-hospital-drug-treatment-of-convulsive-status-epilepticus-in-adults/"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Lorazepam Macure 4mg/ml solution for injection — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/12318/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Lorazepam — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=lorazepam"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Lorazepam — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=lorazepam"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Lorazepam — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=lorazepam"},{"accessed":"2026-10-30","publisher":"www.resus.org.uk","title":"Lorazepam — targeted dosing/safety source (Convulsive status epilepticus algorithm)","url":"https://www.resus.org.uk/sites/default/files/2026-02/RCUK%20Paediatric%20emergency%20algorithms%20and%20resources%20Feb%2026%20V6.pdf"},{"accessed":"2026-10-30","publisher":"www.nice.org.uk","title":"Lorazepam — targeted dosing/safety source (7.1.8–7.1.9)","url":"https://www.nice.org.uk/guidance/ng217/chapter/7-Treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures"},{"accessed":"2026-10-30","publisher":"www.rightdecisions.scot.nhs.uk","title":"Lorazepam — targeted dosing/safety source (Adultstatuspathway)","url":"https://www.rightdecisions.scot.nhs.uk/nhs-borders-clinical-guidelines/drugs-and-therapeutics/in-hospital-drug-treatment-of-convulsive-status-epilepticus-in-adults/"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Lorazepam Macure 4mg/ml solution for injection — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/12318/smpc"},{"title":"Epilepsies, NG217, section 7.1, convulsive status epilepticus","publisher":"NICE","accessed":"2026-11-19","url":"https://www.nice.org.uk/guidance/ng217/chapter/treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures"}],"sources":["https://www.nice.org.uk/guidance/ng217/chapter/treating-status-epilepticus-repeated-or-cluster-seizures-and-prolonged-seizures"]}]},{"table":"drugs","id":"9bbb2af9-38c8-4979-8a07-4dc93d32a51d","guard":{"slug":"dantrolene"},"edits":[{"path":["presentation"],"before":"UK examples include Dantrium IV 20 mg and Agilus 120 mg. The vial strengths, excipients and resulting concentrations differ. Identify the actual product before preparation.","after":"UK Agilus contains 120 mg per vial. SALG reported in July 2025 that the former UK Dantrium IV 20 mg vial was withdrawn. Confirm the actual product before preparing it because the vial strength and preparation differ.","sources":["https://www.salg.ac.uk/salg-publications/salg-statements/salg-statement-on-changes-to-the-formulation-of-dantrolene/"]},{"path":["preparation"],"before":"Dantrium IV 20 mg: add 60 mL sterile water for injections (about 0.33 mg/mL), dissolve and withdraw through the supplied single-use filter. Agilus 120 mg: add 20 mL water for injections. The labelled final concentration is 5.3 mg/mL. Follow section 6.6 of the specific product information for preparation and handling.","after":"UK Agilus 120 mg: add 20 mL of water for injections and shake until dissolved. The final volume is 22.6 mL, containing 5.3 mg/mL. Check for particles before use. Follow the named SmPC section 6.6. Historically, Dantrium IV 20 mg required 60 mL water for injections and use of the supplied filter. Those instructions were specific to that former UK presentation.","sources":["https://www.medicines.org.uk/emc/product/15912/smpc"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Dantrolene — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=dantrolene"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Dantrolene — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=dantrolene"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Dantrolene — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=dantrolene"},{"accessed":"2026-10-30","publisher":"www.emhg.org","title":"Dantrolene — targeted dosing/safety source (Premedication)","url":"https://www.emhg.org/recommendations-1/2018/2/27/perioperative-management-of-mh-suspected-or-susceptible-patients"},{"accessed":"2026-11-19","publisher":"European Malignant Hyperthermia Group","title":"Acute crisis treatment and observation, Box 2 (2024)","url":"https://www.emhg.org/recommendations-1/2024/11/4/recognising-and-managing-a-malignant-hyperthermia-crisis-v2024"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium","title":"Dantrium IV 20 mg, UK SmPC §§4.2–4.5 and 6.6","url":"https://www.medicines.org.uk/emc/product/1097/smpc"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium","title":"Agilus 120 mg, UK SmPC §§2, 4.2–4.3 and 6.6","url":"https://www.medicines.org.uk/emc/product/15912/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Dantrolene — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=dantrolene"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Dantrolene — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=dantrolene"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Dantrolene — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=dantrolene"},{"accessed":"2026-10-30","publisher":"www.emhg.org","title":"Dantrolene — targeted dosing/safety source (Premedication)","url":"https://www.emhg.org/recommendations-1/2018/2/27/perioperative-management-of-mh-suspected-or-susceptible-patients"},{"accessed":"2026-11-19","publisher":"European Malignant Hyperthermia Group","title":"Acute crisis treatment and observation, Box 2 (2024)","url":"https://www.emhg.org/recommendations-1/2024/11/4/recognising-and-managing-a-malignant-hyperthermia-crisis-v2024"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium","title":"Dantrium IV 20 mg, UK SmPC §§4.2–4.5 and 6.6","url":"https://www.medicines.org.uk/emc/product/1097/smpc"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium","title":"Agilus 120 mg, UK SmPC §§2, 4.2–4.3 and 6.6","url":"https://www.medicines.org.uk/emc/product/15912/smpc"},{"title":"Statement on changes to the formulation of dantrolene (28 July 2025)","publisher":"Safe Anaesthesia Liaison Group","accessed":"2026-11-19","url":"https://www.salg.ac.uk/salg-publications/salg-statements/salg-statement-on-changes-to-the-formulation-of-dantrolene/"}],"sources":["https://www.medicines.org.uk/emc/product/15912/smpc","https://www.salg.ac.uk/salg-publications/salg-statements/salg-statement-on-changes-to-the-formulation-of-dantrolene/"]}]},{"table":"drugs","id":"a03049d0-115e-4b01-915d-10c0a73910eb","guard":{"slug":"adrenaline"},"edits":[{"path":["dosing"],"before":"Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.\nAdults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.\nPaediatric anaphylaxis with a pulse, IM 1 mg/mL: under 6 months 100–150 micrograms; 6 months to under 6 years 150 micrograms; 6–12 years 300 micrograms; over 12 years 500 micrograms, or 300 micrograms for a small or prepubertal child. Repeat after 5 minutes for persistent airway, breathing or circulation problems.\nPaediatric cardiac arrest outside the newborn-at-birth pathway: 10 micrograms/kg IV/IO (0.1 mL/kg of 0.1 mg/mL), maximum 1 mg, every 3–5 minutes according to the PALS algorithm. Titrate vasoactive infusions in critical care to the specific indication, haemodynamics and local concentration protocol.","after":"Adult cardiac arrest: 1 mg IV/IO of 0.1 mg/mL under the adult ALS algorithm, repeated every 3–5 minutes. Follow the rhythm-specific timing of the first dose.\nAdults with suspected anaphylaxis and a pulse: give 500 micrograms IM (0.5 mL of 1 mg/mL) in the anterolateral thigh. If airway, breathing or circulation problems persist, repeat after 5 minutes. In refractory anaphylaxis seek expert help for a monitored IV adrenaline infusion. An IV bolus in a patient with a pulse is restricted to appropriately experienced clinicians in an appropriate specialist setting.\nPaediatric anaphylaxis with a pulse, IM 1 mg/mL: under 6 months 100–150 micrograms; 6 months to under 6 years 150 micrograms; 6–12 years 300 micrograms; over 12 years 500 micrograms, or 300 micrograms for a small or prepubertal child. Repeat after 5 minutes for persistent airway, breathing or circulation problems.\nPaediatric cardiac arrest outside the newborn-at-birth pathway: 10 micrograms/kg IV/IO (0.1 mL/kg of 0.1 mg/mL), maximum 1 mg, every 3–5 minutes according to the PALS algorithm. Titrate vasoactive infusions in critical care to the specific indication, haemodynamics and local concentration protocol.\nNewborn resuscitation at birth (RCUK 2025 NLS): if HR remains below 60/min and is not rising despite effective ventilation, airway control and at least 30 seconds of chest compressions, give 20 micrograms/kg via umbilical vein (preferred) or IO, using 0.2 mL/kg of 0.1 mg/mL adrenaline. Repeat every 4 minutes while HR remains below 60/min. If intubated without vascular access, give 100 micrograms/kg intratracheally (1 mL/kg of the same solution). If HR is still below 60/min when vascular access becomes available, give the vascular dose immediately irrespective of the timing of the tracheal dose.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/newborn-resuscitation-and-support-transition-infants-birth"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adrenaline (epinephrine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adrenaline (epinephrine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adrenaline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adrenaline (epinephrine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"accessed":"2026-11-19","publisher":"Resuscitation Council UK","title":"Adult resuscitation in special circumstances, 2025: anaphylaxis","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"accessed":"2026-11-19","publisher":"Resuscitation Council UK","title":"Emergency treatment of anaphylaxis: IM dosing by age, repeat dose and refractory treatment","url":"https://www.resus.org.uk/sites/default/files/2021-05/Emergency%20Treatment%20of%20Anaphylaxis%20May%202021_0.pdf"},{"accessed":"2026-11-19","publisher":"NHS Scotland / Right Decisions","title":"Adult IV adrenaline: named concentrations, dilution and monitoring","url":"https://www.rightdecisions.scot.nhs.uk/media/ei1jmppt/adult-adrenaline_epinephrine-intravenous-version-9.pdf"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Adrenaline (epinephrine) — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Adrenaline (epinephrine) — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=adrenaline"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Adrenaline (epinephrine) — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=adrenaline"},{"accessed":"2026-09-13","publisher":"Critical Care Medicine / SCCM–ESICM","title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021","url":"https://doi.org/10.1097/CCM.0000000000005337"},{"accessed":"2026-11-19","publisher":"Resuscitation Council UK","title":"Adult resuscitation in special circumstances, 2025: anaphylaxis","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines"},{"accessed":"2026-11-19","publisher":"Resuscitation Council UK","title":"Emergency treatment of anaphylaxis: IM dosing by age, repeat dose and refractory treatment","url":"https://www.resus.org.uk/sites/default/files/2021-05/Emergency%20Treatment%20of%20Anaphylaxis%20May%202021_0.pdf"},{"accessed":"2026-11-19","publisher":"NHS Scotland / Right Decisions","title":"Adult IV adrenaline: named concentrations, dilution and monitoring","url":"https://www.rightdecisions.scot.nhs.uk/media/ei1jmppt/adult-adrenaline_epinephrine-intravenous-version-9.pdf"},{"title":"Newborn resuscitation and support of transition of infants at birth, Guidelines 2025","publisher":"Resuscitation Council UK","accessed":"2026-11-19","url":"https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/newborn-resuscitation-and-support-transition-infants-birth"}],"sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/newborn-resuscitation-and-support-transition-infants-birth"]}]},{"table":"drugs","id":"b20909c1-897e-4d59-a395-0cbd215c5dda","guard":{"slug":"amikacin"},"edits":[{"path":["adult_bolus_dose"],"before":"• Systemic infections (once-daily dosing): 15 mg/kg IV once daily (max 1.5 g/day). \n• Systemic infections (conventional dosing): 5–7.5 mg/kg daily in 2–3 divided doses. \n• Doses for obese patients calculated on adjusted body weight (ideal body weight + 40% of excess weight); consult specialist.","after":"• Systemic infections (once-daily dosing): In adults with normal renal function, 15 mg/kg IV once daily (maximum 1.5 g/day) when the indication permits. The named SmPC specifies twice-daily dosing for endocarditis and febrile neutropenia. Use local microbiology and drug-level guidance. \n• Systemic infections (conventional dosing): Adults with normal renal function: 15 mg/kg/day total, divided as 7.5 mg/kg every 12 hours or 5 mg/kg every 8 hours, maximum 1.5 g/day. Give IV by infusion over 30–60 minutes. Individualise according to renal function, measured levels and the indication. \n• Doses for obese patients calculated on adjusted body weight (ideal body weight + 40% of excess weight); consult specialist.","sources":["https://www.medicines.org.uk/emc/product/11189/smpc"]},{"path":["dosing"],"before":"• Adults (once-daily dosing for systemic infections): 15 mg/kg IV once daily (max 1.5 g/day). \n• Adults (conventional dosing for systemic infections): 15 mg/kg/day in divided doses (7.5 mg/kg every 12 hours or 5 mg/kg every 8 hours; maximum 1.5 g/day), for adults with normal renal function. \n• Renal Impairment: Adjust dose/interval based on creatinine clearance and plasma-levels. Refer to local guidelines/dosage nomograms. \n• Paediatrics: Neonates (pre-term and full-term <4 weeks) 7.5 mg/kg every 12 hours. Infants (4 weeks–12 years) 15–20 mg/kg once daily or 7.5 mg/kg every 12 hours. \n• Elderly: Dose adjustment required based on renal function and body weight.","after":"• Adults (once-daily dosing for systemic infections): In adults with normal renal function, 15 mg/kg IV once daily (maximum 1.5 g/day) when the indication permits. The named SmPC specifies twice-daily dosing for endocarditis and febrile neutropenia. Use local microbiology and drug-level guidance. \n• Adults (conventional dosing for systemic infections): 15 mg/kg/day in divided doses (7.5 mg/kg every 12 hours or 5 mg/kg every 8 hours; maximum 1.5 g/day), for adults with normal renal function. \n• Renal Impairment: Adjust dose/interval based on creatinine clearance and plasma-levels. Refer to local guidelines/dosage nomograms. \n• Paediatrics: The named SmPC distinguishes term neonates (10 mg/kg initially, then 7.5 mg/kg every 12 hours) from preterm infants (7.5 mg/kg every 12 hours). Follow neonatal unit dosing and level monitoring by gestational age and renal function. Infants (4 weeks–12 years) 15–20 mg/kg once daily or 7.5 mg/kg every 12 hours. \n• Elderly: Dose adjustment required based on renal function and body weight.","sources":["https://www.medicines.org.uk/emc/product/11189/smpc"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Amikacin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=amikacin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Amikacin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=amikacin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Amikacin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=amikacin"},{"accessed":"2026-09-13","publisher":"NICE","title":"Sepsis: recognition, diagnosis and early management (NG51)","url":"https://www.nice.org.uk/guidance/ng51"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Amikacin — targeted dosing/safety source (4.2, accessed2026-10-30)","url":"https://www.medicines.org.uk/emc/product/14189/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Amikacin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=amikacin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Amikacin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=amikacin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Amikacin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=amikacin"},{"accessed":"2026-09-13","publisher":"NICE","title":"Sepsis: recognition, diagnosis and early management (NG51)","url":"https://www.nice.org.uk/guidance/ng51"},{"accessed":"2026-10-30","publisher":"electronic Medicines Compendium (emc)","title":"Amikacin — targeted dosing/safety source (4.2, accessed2026-10-30)","url":"https://www.medicines.org.uk/emc/product/14189/smpc"},{"title":"Amikacin 250 mg/mL injection/infusion, UK SmPC, section 4.2","publisher":"electronic Medicines Compendium","accessed":"2026-11-19","url":"https://www.medicines.org.uk/emc/product/11189/smpc"}],"sources":["https://www.medicines.org.uk/emc/product/11189/smpc"]}]},{"table":"drugs","id":"c4d6a68e-897b-4681-97c9-3d26e1e4dbca","guard":{"slug":"plasma-lyte"},"edits":[{"path":["infusion_range"],"before":"Dependent on clinical need. Typical infusion rates 1-3 mL/kg/hour in adults. Maximum 40 mL/kg/24 hours in adults, adolescents, and children.","after":"Individualise the infusion rate and volume to age, weight, indication, measured losses and response. The named UK SmPC describes 40 mL/kg over 24 hours as a usual rate in adults and adolescents. Children have separate weight-banded guidance. Reassess fluid balance, electrolytes and acid–base status during treatment.","sources":["https://www.medicines.org.uk/emc/product/1795/smpc"]},{"path":["dosing"],"before":"• Adults, adolescents, and children: Dose depends on clinical condition, weight, and concomitant therapy. Maximum 40 mL/kg/24 hours.\n• Elderly/Renal/Hepatic impairment: Administer with caution due to risk of fluid overload, hyperkalaemia, and hypermagnesaemia.","after":"Adults and adolescents: individualise the rate and total volume. The named UK Plasma-Lyte 148 (pH 7.4) SmPC gives 500 mL to 3 litres in 24 hours as its recommended range and describes 40 mL/kg/24 h as a usual rate. Children: apply the product’s separate weight-banded table and the paediatric fluid pathway for the clinical indication. In older adults and those with cardiac, hepatic or renal impairment, review comorbidity, fluid balance and electrolytes when selecting therapy. For this product, renal failure and hyperkalaemia are contraindications.","sources":["https://www.medicines.org.uk/emc/product/1795/smpc"]},{"path":["key_warning"],"before":"Administer with caution in severe renal impairment due to risk of hyperkalaemia, hypermagnesaemia, and fluid overload.","after":"The UK Plasma-Lyte 148 (pH 7.4) SmPC lists renal failure and hyperkalaemia as contraindications. In other renal impairment, monitor the risk of fluid overload and sodium, potassium and magnesium retention.","sources":["https://www.medicines.org.uk/emc/product/1795/smpc"]},{"path":["contraindications"],"before":"• Hypersensitivity to active substances or excipients.\n• Severe hyperkalaemia, hypermagnesaemia, or hypernatraemia.\n• Severe metabolic alkalosis.\n• Severe renal insufficiency (with oliguria/anuria).\n• Decompensated cardiac failure, acute pulmonary oedema, or hyperhydration.\n• Untreated Addison's disease.","after":"Named UK Plasma-Lyte 148 (pH 7.4), SmPC section 4.3: hyperkalaemia, renal failure, heart block, metabolic or respiratory alkalosis, hypochlorhydria, or hypersensitivity to the product. Separately, section 4.4 advises caution and monitoring in patients at risk of electrolyte or fluid overload, including those with renal impairment, cardiac or pulmonary failure and hypervolaemia.","sources":["https://www.medicines.org.uk/emc/product/1795/smpc"]}]},{"table":"drugs","id":"cbe47b89-c131-4ac3-af06-88101e5f90eb","guard":{"slug":"aspirin"},"edits":[{"path":["adult_bolus_dose"],"before":"• Acute Coronary Syndrome/Acute Ischaemic Stroke/TIA: 150 mg or 300 mg oral loading dose (chewed or dispersed).\n• Secondary prevention of thrombotic events: 75 mg or 150 mg oral once daily.","after":"• UK acute coronary syndromes: 300 mg as a single loading dose as soon as possible unless contraindicated (NICE NG185). Suspected TIA: 300 mg daily immediately unless contraindicated, with urgent specialist assessment. Acute ischaemic stroke: give 300 mg after brain imaging excludes intracerebral haemorrhage, as soon as possible and within 24 hours if eligible. Use oral aspirin if swallowing is safe, or rectal/enteral administration if appropriate. After thrombolysis wait at least 24 hours and exclude significant haemorrhage before starting an antiplatelet. Follow the stroke team’s acute and secondary-prevention regimen (NICE NG128 and National Clinical Guideline for Stroke).\n• Secondary prevention of thrombotic events: 75 mg or 150 mg oral once daily.","sources":["https://www.nice.org.uk/guidance/ng128/chapter/recommendations"]},{"path":["dosing"],"before":"• Cardiovascular Indications (e.g., ACS, Stroke, TIA, Secondary Prevention):\n  • Loading dose: 150–300 mg oral (chewed/dispersed) for ACS/acute ischaemic stroke/TIA.\n  • Maintenance: 75 mg once daily; 150 mg once daily for high-risk patients (BNF guidance).\n• Pain/Fever/Inflammation (short term):\n  • Adult: 300–900 mg oral every 4–6 hours, max 4 g/day.\n• Paediatric: Not for children and adolescents under 16 years unless specifically indicated (e.g., Kawasaki disease) due to risk of Reye’s syndrome.\n• Renal impairment: use with caution if eGFR <30 mL/min; avoid if eGFR <10 mL/min or if on dialysis. SPC contraindicates in severe renal impairment (eGFR <30 mL/min for some products).","after":"• Cardiovascular Indications (e.g., ACS, Stroke, TIA, Secondary Prevention):\n  • UK acute coronary syndromes: 300 mg as a single loading dose as soon as possible unless contraindicated (NICE NG185). Suspected TIA: 300 mg daily immediately unless contraindicated, with urgent specialist assessment. Acute ischaemic stroke: give 300 mg after brain imaging excludes intracerebral haemorrhage, as soon as possible and within 24 hours if eligible. Use oral aspirin if swallowing is safe, or rectal/enteral administration if appropriate. After thrombolysis wait at least 24 hours and exclude significant haemorrhage before starting an antiplatelet. Follow the stroke team’s acute and secondary-prevention regimen (NICE NG128 and National Clinical Guideline for Stroke). Under NICE NG128 the usual acute ischaemic stroke aspirin course is 300 mg daily until two weeks after symptom onset, followed by definitive long-term antithrombotic treatment. Specialist pathways may select earlier dual antiplatelet therapy for eligible TIA or minor stroke. Select long-term therapy by indication.\n• Pain/Fever/Inflammation (short term):\n  • Adult: 300–900 mg oral every 4–6 hours, max 4 g/day.\n• Paediatric: Not for children and adolescents under 16 years unless specifically indicated (e.g., Kawasaki disease) due to risk of Reye’s syndrome.\n• Renal impairment: use with caution if eGFR <30 mL/min; avoid if eGFR <10 mL/min or if on dialysis. SPC contraindicates in severe renal impairment (eGFR <30 mL/min for some products).","sources":["https://www.nice.org.uk/guidance/ng128/chapter/recommendations"]},{"path":["sources"],"before":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Aspirin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=aspirin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Aspirin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=aspirin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Aspirin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=aspirin"},{"accessed":"2026-09-13","publisher":"NICE","title":"Venous thromboembolism in over 16s (NG89)","url":"https://www.nice.org.uk/guidance/ng89"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Aspirin 75 mg tablets — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/102206/smpc"}],"after":[{"accessed":"2026-09-13","publisher":"British National Formulary (NICE)","title":"Aspirin — BNF monograph","url":"https://bnf.nice.org.uk/search/?q=aspirin"},{"accessed":"2026-09-13","publisher":"electronic Medicines Compendium (emc), Datapharm","title":"Aspirin — Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/search?q=aspirin"},{"accessed":"2026-09-13","publisher":"BNF for Children (NICE)","title":"Aspirin — BNF for Children monograph","url":"https://bnfc.nice.org.uk/search/?q=aspirin"},{"accessed":"2026-09-13","publisher":"NICE","title":"Venous thromboembolism in over 16s (NG89)","url":"https://www.nice.org.uk/guidance/ng89"},{"accessed":"2026-11-19","publisher":"electronic Medicines Compendium (emc), Datapharm","reviewNote":"Document and presentation identity checked on 19 November 2026. Full claim-level clinical review remains outstanding.","scope":"Named presentation and route only. Check the relevant product section for the particular indication, population or dose.","title":"Aspirin 75 mg tablets — UK Summary of Product Characteristics","url":"https://www.medicines.org.uk/emc/product/102206/smpc"},{"title":"Stroke and transient ischaemic attack in over 16s, NG128","publisher":"NICE","accessed":"2026-11-19","url":"https://www.nice.org.uk/guidance/ng128/chapter/recommendations"}],"sources":["https://www.nice.org.uk/guidance/ng128/chapter/recommendations"]}]},{"table":"podcasts","id":"1fbb3803-8e7e-4acb-923a-37a896b83e29","guard":{"topic_id":"muscle-relaxants","script_md5":"0c85577d4e9165fddfdb7ec4595c3f23","audio_path_md5":"2af2e37279bb77a60580a6bbdea5efb3","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue for CICO and gives misleading routine deep-block dosing. DAS 2025 requires immediate emergency front-of-neck airway once other routes fail. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"33aa8a80-094d-48cb-b6e0-6aef9f3c6173","guard":{"topic_id":"muscle-relaxants","script_md5":"9c626b988ad483b0c822c85f83730292","audio_path_md5":"86ad7a374c1b9eaa03905be94f18bad6","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue after intubation and oxygenation fail. The DAS 2025 CICO pathway requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"38c0148d-d868-4b73-8ce9-253c34bbd549","guard":{"topic_id":"muscle-relaxants","script_md5":"9c626b988ad483b0c822c85f83730292","audio_path_md5":"7b655c896e102cf97d5b8157ea193fef","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue after intubation and oxygenation fail. The DAS 2025 CICO pathway requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"444e6db2-cbea-4b36-9748-a6d3a0ec869b","guard":{"topic_id":"bariatric-anaesthesia","script_md5":"6cd3cd4a375d842cdd18f5c59c8d6027","audio_path_md5":"3f98dd89725e531a43669a86457e69b1","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://www.medicines.org.uk/emc/product/6409/smpc"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://www.medicines.org.uk/emc/product/6409/smpc"]},{"path":["audit_hold_reason"],"before":null,"after":"The script repeatedly recommends adjusted weight for sugammadex in obesity. The UK product information specifies actual body weight, including for morbid obesity. Source: https://www.medicines.org.uk/emc/product/6409/smpc","sources":["https://www.medicines.org.uk/emc/product/6409/smpc"]}]},{"table":"podcasts","id":"62f87540-6e47-4b8d-81c7-b1f80f4bd8bb","guard":{"topic_id":"renal-disease","script_md5":"a992710460699bcecb27caf12c5b89ac","audio_path_md5":"9908fd9e2b34e09b78882025a7b007db","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches giving 30 mL of 10% calcium gluconate for hyperkalaemia over 2–5 minutes in a patient with a circulation. MHRA specifies slow IV administration over 10 minutes. Source: https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia","sources":["https://www.gov.uk/drug-safety-update/calcium-chloride-calcium-gluconate-potential-risk-of-underdosing-with-calcium-gluconate-in-severe-hyperkalaemia"]}]},{"table":"podcasts","id":"7cc1aa46-3f63-422c-99a9-e883e514d2ca","guard":{"topic_id":"ophthalmic-anaesthesia","script_md5":"83a4875aa94f4c0bad8457659fb8a536","audio_path_md5":"d02e3bc53343a359919b36f5344af971","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script tells learners their rescue plan relies on sugammadex when intubation and ventilation fail. CICO requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"a375ab08-0cfd-42e9-8867-406705a01b15","guard":{"topic_id":"rocuronium","script_md5":"35bbb76cb4f73c373e283bd52070270d","audio_path_md5":"bda8764063e73d2b31deaf2845a52798","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script presents sugammadex as rescue in a cannot-intubate, cannot-ventilate emergency. Drug reversal must never delay the DAS CICO response. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"c271c798-b564-4c28-a6fa-eab5a3b8ac38","guard":{"topic_id":"muscle-relaxants","script_md5":"9c626b988ad483b0c822c85f83730292","audio_path_md5":"3d982bbc22f46d286ebbc4877d70d69e","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue after intubation and oxygenation fail. The DAS 2025 CICO pathway requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"c41ee99d-084f-4a96-835b-8f2d6d754972","guard":{"topic_id":"gi-physiology","script_md5":"37e8cfb5a8291044905eb14f59c1b84b","audio_path_md5":"7fe34409a35122380af3b5a61680ffcb","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://das.uk.com/guidelines/obstetric_airway_guidelines_2015/"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://das.uk.com/guidelines/obstetric_airway_guidelines_2015/"]},{"path":["audit_hold_reason"],"before":null,"after":"The script categorically prohibits facemask ventilation during induction in pregnancy. OAA/DAS supports considering gentle facemask ventilation after induction to reduce desaturation risk. Source: https://das.uk.com/guidelines/obstetric_airway_guidelines_2015/","sources":["https://das.uk.com/guidelines/obstetric_airway_guidelines_2015/"]}]},{"table":"podcasts","id":"ed97cf23-4d94-40fc-b1ae-aa6c0b899872","guard":{"topic_id":"muscle-relaxants","script_md5":"9c626b988ad483b0c822c85f83730292","audio_path_md5":"82464b881fb9a9c709cacb36889ea183","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue after intubation and oxygenation fail. The DAS 2025 CICO pathway requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"podcasts","id":"ffe09ff0-9b63-4ad2-b868-c2cbfc7b7ca8","guard":{"topic_id":"muscle-relaxants","script_md5":"9c626b988ad483b0c822c85f83730292","audio_path_md5":"552ee5c35e706d22871e276b2a8f9ad2","regenerating":false},"edits":[{"path":["audit_hold"],"before":false,"after":true,"sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["status"],"before":"ready","after":"failed","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["audit_hold_reason"],"before":null,"after":"The script teaches sugammadex as rescue after intubation and oxygenation fail. The DAS 2025 CICO pathway requires immediate emergency front-of-neck airway. Source: https://doi.org/10.1016/j.bja.2025.10.006","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"viva_model_answers","id":"042e54d1-3939-405d-95aa-452a14dd2e88","guard":{},"edits":[{"path":["model_answer"],"before":"Hypersensitivity reactions are exaggerated or inappropriate immune responses to an antigen. They are traditionally classified by the Gell and Coombs system into four types.\n\nType I (Immediate) is IgE-mediated. Upon re-exposure to an allergen, cross-linking of IgE on mast cells and basophils causes degranulation, releasing histamine, leukotrienes, and tryptase. This is the mechanism of clinical anaphylaxis. In anaesthesia, common triggers include NMBAs (specifically Suxamethonium and Rocuromium), antibiotics, and latex.\n\nType II (Cytotoxic) involves IgG or IgM antibodies binding to antigens on cell surfaces, leading to cell lysis via the complement system or phagocytosis. An example is an acute haemolytic transfusion reaction or Goodpasture’s syndrome.\n\nType III (Immune-complex) occurs when antigen-antibody complexes deposit in tissues (like basement membranes), triggering inflammation. Examples include systemic lupus erythematosus (SLE) or extrinsic allergic alveolitis.\n\nType IV (Delayed-type) is cell-mediated rather than antibody-mediated. Sensitised T-lymphocytes release cytokines 48–72 hours after exposure. This is seen in contact dermatitis or the tuberculin skin test.\n\nClinically, Type I is most relevant to the anaesthetist due to its rapid onset and potential for airway obstruction and refractory hypotension. Management follows the AAGBI/ALS guidelines (Adrenaline 50mcg IV titrated for Grade 3/4).","after":"Hypersensitivity reactions are exaggerated or inappropriate immune responses to an antigen. They are traditionally classified by the Gell and Coombs system into four types.\n\nType I (Immediate) is IgE-mediated. Upon re-exposure to an allergen, cross-linking of IgE on mast cells and basophils causes degranulation, releasing histamine, leukotrienes, and tryptase. This is the mechanism of clinical anaphylaxis. In anaesthesia, common triggers include NMBAs (specifically Suxamethonium and Rocuromium), antibiotics, and latex.\n\nType II (Cytotoxic) involves IgG or IgM antibodies binding to antigens on cell surfaces, leading to cell lysis via the complement system or phagocytosis. An example is an acute haemolytic transfusion reaction or Goodpasture’s syndrome.\n\nType III (Immune-complex) occurs when antigen-antibody complexes deposit in tissues (like basement membranes), triggering inflammation. Examples include systemic lupus erythematosus (SLE) or extrinsic allergic alveolitis.\n\nType IV (Delayed-type) is cell-mediated rather than antibody-mediated. Sensitised T-lymphocytes release cytokines 48–72 hours after exposure. This is seen in contact dermatitis or the tuberculin skin test.\n\nClinically, Type I is most relevant to the anaesthetist due to its rapid onset and potential for airway obstruction and refractory hypotension. In adult perioperative anaphylaxis with a circulation, an experienced anaesthetist/intensivist gives an initial 50 micrograms IV adrenaline with monitoring and titrates to response alongside rapid crystalloid. Start CPR if systolic BP falls below 50 mmHg or cardiac arrest occurs. In established adult cardiac arrest, follow ALS adrenaline dosing and timing. RCUK perioperative anaphylaxis algorithm: https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf","sources":["https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]}]},{"table":"viva_model_answers","id":"04563efe-016a-4be5-b460-181cd2cfe88c","guard":{},"edits":[{"path":["model_answer"],"before":"Emergency Front of Neck Access (eFONA) is the final stage (Plan D) of the difficult airway algorithm, performed when both intubation and rescue oxygenation (SAD and face mask) have failed, resulting in a 'Cannot Intubate, Cannot Oxygenate' (CICO) situation. \n\nThe DAS-recommended technique is the Scalpel-Bougie-Tube approach. The patient's neck is placed in full extension to expose the cricothyroid membrane (CTM). The 'laryngeal handshake' is used to stabilize the larynx and identify the CTM. A transverse incision is made through the CTM using a size 10 blade. The blade is turned 90 degrees to maintain the opening, and a coudé-tipped bougie is passed into the trachea. A 6.0mm cuffed endotracheal tube is then railroaded over the bougie, the cuff inflated, and position confirmed with capnography.\n\nIn the ICU setting, obesity, neck edema, and previous surgery often obscure landmarks. In such cases, a vertical midline skin incision may be required first to facilitate identification of the CTM. Clinical relevance is critical: delays in performing eFONA lead to hypoxic brain injury and cardiac arrest. Key figures include the 6.0mm tube size (large enough for ventilation/suction, small enough for the CTM) and the importance of excluding needle cricothyroidotomy in adults due to high failure rates and inadequate ventilation.","after":"Emergency Front of Neck Access (eFONA) is the final stage (Plan D) of the difficult airway algorithm, performed when both intubation and rescue oxygenation (SAD and face mask) have failed, resulting in a 'Cannot Intubate, Cannot Oxygenate' (CICO) situation. \n\nThe DAS-recommended technique is the Scalpel-Bougie-Tube approach. The patient's neck is placed in full extension to expose the cricothyroid membrane (CTM). The 'laryngeal handshake' is used to stabilize the larynx and identify the CTM. A transverse incision is made through the CTM using a size 10 blade. The blade is turned 90 degrees to maintain the opening, and a coudé-tipped bougie is passed into the trachea. A 6.0mm cuffed endotracheal tube is then railroaded over the bougie, the cuff inflated, and position confirmed with capnography.\n\nIn the ICU setting, obesity, neck edema, and previous surgery often obscure landmarks. DAS 2025 recommends a vertical midline skin incision as the default when palpability has not been explicitly assessed or is uncertain. Identify and stabilise the larynx and membrane before the transverse membrane incision. A direct transverse approach requires reliably identified landmarks. Source: https://doi.org/10.1016/j.bja.2025.10.006 Clinical relevance is critical: delays in performing eFONA lead to hypoxic brain injury and cardiac arrest. Key figures include the 6.0mm tube size (large enough for ventilation/suction, small enough for the CTM) and the importance of excluding needle cricothyroidotomy in adults due to high failure rates and inadequate ventilation.","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"viva_model_answers","id":"17fe66e7-c8e9-4e71-b016-07a698912efb","guard":{},"edits":[{"path":["model_answer"],"before":"Adenosine is an endogenous purine nucleoside used as a first-line diagnostic and therapeutic agent for stable narrow-complex supraventricular tachycardias (SVT), specifically those involving the Atrioventricular (AV) node, such as AVNRT.\n\nIts mechanism involves binding to G-protein coupled A1 receptors in the AV node. This activation leads to two primary intracellular effects: the inhibition of adenylyl cyclase (decreasing cAMP) and the activation of inward-rectifier potassium channels. This results in hyperpolarisation of the cell membrane and inhibition of Calcium-induced slowest-response action potentials, effectively causing a transient \"chemical cardioversion\" or AV block.\n\nPharmacokinetically, adenosine has an extremely short half-life of less than 10 seconds due to rapid uptake by erythrocytes and vascular endothelial cells, followed by metabolism by adenosine deaminase. Therefore, it must be administered via a large-bore cannula in a proximal vein (e.g., antecubital fossa) as a rapid bolus followed by a vigorous saline flush.\n\nClinical considerations include the 'feeling of impending doom,' chest pain, and bronchospasm. Specifically, it is contraindicated in patients with asthma or high-degree heart block. It is also important to note drug interactions: dipyridamole potentiates its effect (requiring a dose reduction), whereas theophylline and caffeine are competitive antagonists (requiring a dose increase). The standard adult dosing regimen is 6 mg, followed by 12 mg, and a further 12 mg if unsuccessful.","after":"Adenosine is an endogenous purine nucleoside used as a first-line diagnostic and therapeutic agent for stable narrow-complex supraventricular tachycardias (SVT), specifically those involving the Atrioventricular (AV) node, such as AVNRT.\n\nIts mechanism involves binding to G-protein coupled A1 receptors in the AV node. This activation leads to two primary intracellular effects: the inhibition of adenylyl cyclase (decreasing cAMP) and the activation of inward-rectifier potassium channels. This results in hyperpolarisation of the cell membrane and inhibition of Calcium-induced slowest-response action potentials, effectively causing a transient \"chemical cardioversion\" or AV block.\n\nPharmacokinetically, adenosine has an extremely short half-life of less than 10 seconds due to rapid uptake by erythrocytes and vascular endothelial cells, followed by metabolism by adenosine deaminase. Therefore, it must be administered via a large-bore cannula in a proximal vein (e.g., antecubital fossa) as a rapid bolus followed by a vigorous saline flush.\n\nClinical considerations include the 'feeling of impending doom,' chest pain, and bronchospasm. Specifically, it is contraindicated in patients with asthma or high-degree heart block. It is also important to note drug interactions: dipyridamole potentiates adenosine and concomitant use should usually be avoided. If essential, a much smaller adenosine dose may be needed. Xanthines such as theophylline and caffeine can antagonise its effect. Follow the applicable product guidance and rhythm algorithm. For an adult with stable regular narrow-complex tachycardia persisting after vagal manoeuvres, with no pre-excitation or other contraindication, the RCUK algorithm uses adenosine 6 mg as a rapid IV bolus followed by a flush. If unsuccessful, give 12 mg, then 18 mg if needed. Further assessment and treatment follow the rhythm algorithm. RCUK adult tachyarrhythmia algorithm, March 2026: https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf","sources":["https://www.medicines.org.uk/emc/medicine/25016/spc","https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]},{"path":["high_yield_points","4"],"before":"Dosing: 6mg, 12mg, 12mg rapid bolus with flush","after":"Stable regular narrow-complex tachycardia without pre-excitation: vagal manoeuvres, then rapid IV adenosine 6 mg, 12 mg and 18 mg as indicated (RCUK March 2026).","sources":["https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]}]},{"table":"viva_model_answers","id":"211ebdae-dcad-46fc-9c1a-4cfe9b0d1da7","guard":{},"edits":[{"path":["model_answer"],"before":"Post-resuscitation care represents the fifth link in the 'Chain of Survival' and is a multi-system approach to managing the Post-Cardiac Arrest Syndrome. This syndrome comprises post-arrest brain injury, post-arrest myocardial dysfunction, the systemic ischemia-reperfusion response, and the persistent precipitating pathology.\n\nManagement is structured via the ABCDE approach. Respiratory targets involve titrating FiO2 to maintain oxygen saturations of 94-98% (avoiding hyperoxaemia) and achieving normocapnia (PaCO2 4.5-6.0 kPa) to protect cerebral blood flow. Cardiovascularly, an immediate 12-lead ECG is mandatory; if STEMI is present, the patient requires immediate coronary angiography. MAP should be targeted to achieve adequate urine output (>0.5ml/kg/hr) and normalise lactate, typically >65 mmHg.\n\nRegarding temperature, the landmark TTM2 trial (2021) has shifted practice. Current guidelines recommend maintaining a target temperature of ≤37.5°C (normothermia). Active cooling is reserved for patients who develop a fever (>37.7°C). Routine therapeutic hypothermia (32-34°C) is no longer recommended. \n\nFinally, neuroprognostication must be delayed. To avoid premature withdrawal of life-sustaining treatment (WLST), a multimodal assessment is mandated, typically no earlier than 72 hours after ROSC, provided confounding factors such as sedation and metabolic derangements are excluded. Monitoring should include continuous EEG to detect non-convulsive status epilepticus, which occurs in approximately 20-30% of comatose survivors.","after":"Post-resuscitation care represents the fifth link in the 'Chain of Survival' and is a multi-system approach to managing the Post-Cardiac Arrest Syndrome. This syndrome comprises post-arrest brain injury, post-arrest myocardial dysfunction, the systemic ischemia-reperfusion response, and the persistent precipitating pathology.\n\nManagement is structured via the ABCDE approach. Respiratory targets involve titrating FiO2 to maintain oxygen saturations of 94-98% (avoiding hyperoxaemia) and achieving normocapnia (PaCO2 4.7–6.0 kPa) to protect cerebral blood flow. Cardiovascularly, an immediate 12-lead ECG is mandatory; if STEMI is present, the patient requires immediate coronary angiography. MAP should be targeted to achieve adequate urine output (>0.5ml/kg/hr) and normalise lactate, typically >65 mmHg.\n\nRegarding temperature, the landmark TTM2 trial (2021) has shifted practice. Current guidelines recommend maintaining a target temperature of ≤37.5°C (normothermia). In patients who remain comatose, monitor core temperature and actively prevent fever, targeting ≤37.5°C. Use temperature-control measures as needed. RCUK post-resuscitation guidance: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines Routine therapeutic hypothermia (32-34°C) is no longer recommended. \n\nFinally, neuroprognostication must be delayed. To avoid premature withdrawal of life-sustaining treatment (WLST), a multimodal assessment is mandated, typically no earlier than 72 hours after ROSC, provided confounding factors such as sedation and metabolic derangements are excluded. Monitoring should include continuous EEG to detect non-convulsive status epilepticus, which occurs in approximately 20-30% of comatose survivors.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]},{"path":["high_yield_points","3"],"before":"Immediate coronary angiography for STEMI/presumed cardiac cause","after":"Immediate coronary angiography for persistent ST elevation or a high likelihood of acute coronary occlusion, such as haemodynamic or electrical instability.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]}]},{"table":"viva_model_answers","id":"274978dc-bbb1-4a86-a1ef-0fa28aa17b9a","guard":{},"edits":[{"path":["model_answer"],"before":"When presented with an acute tachyarrhythmia in the ICU, my approach is systematic, beginning with an 'ABCDE' assessment to determine clinical stability. I define stability based on the Resus Council UK criteria: the presence of shock, syncope, myocardial ischemia, or heart failure.\n\nI classify the tachycardia based on the QRS duration. A narrow complex (<0.12s) tachycardia is usually supraventricular (SVT). If regular, it may be sinus tachycardia, AVNRT, or atrial flutter; if irregular, it is most commonly atrial fibrillation. A wide complex (>0.12s) tachycardia is considered ventricular tachycardia (VT) until proven otherwise, though it can represent SVT with aberrant conduction or a bundle branch block.\n\nFor unstable patients, immediate synchronised DC cardioversion is indicated, starting at 120-150J for AF or VT, or 70-120J for flutter/SVT. In stable patients, management is pharmacological. For regular narrow-complex tachycardias, vagal manoeuvres are first-line, followed by graduated doses of Adenosine (6 mg, then 12 mg, then a further 12 mg — the 2021 RCUK adult tachycardia algorithm caps the third dose at 12 mg rather than 18 mg). For stable AF, rate control with beta-blockers or diltiazem is preferred unless rhythm control is sought via Amiodarone. For stable VT, an infusion of Amiodarone 300mg over 20-60 minutes is the standard treatment. Throughout, I prioritize correcting underlying ICU triggers such as electrolyte imbalances (K+ >4.0, Mg2+ >1.0), hypoxia, hypercarbia, or sympathetic surge.","after":"When presented with an acute tachyarrhythmia in the ICU, my approach is systematic, beginning with an 'ABCDE' assessment to determine clinical stability. I define stability based on the Resus Council UK criteria: the presence of shock, syncope, myocardial ischemia, or heart failure.\n\nI classify the tachycardia based on the QRS duration. A narrow complex (<0.12s) tachycardia is usually supraventricular (SVT). If regular, it may be sinus tachycardia, AVNRT, or atrial flutter; if irregular, it is most commonly atrial fibrillation. A wide complex (>0.12s) tachycardia is considered ventricular tachycardia (VT) until proven otherwise, though it can represent SVT with aberrant conduction or a bundle branch block.\n\nFor unstable tachyarrhythmia with a pulse, use synchronised cardioversion, with careful sedation or anaesthesia if conscious. For AF, initial maximum defibrillator output is reasonable. For VT with a pulse start at 120–150 J, and for flutter or paroxysmal SVT at 70–120 J. Stable patients need rhythm-specific treatment. Sinus tachycardia calls for treatment of its cause. Source: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines For an adult with stable regular narrow-complex tachycardia persisting after vagal manoeuvres, with no pre-excitation or other contraindication, the RCUK algorithm uses adenosine 6 mg as a rapid IV bolus followed by a flush. If unsuccessful, give 12 mg, then 18 mg if needed. Further assessment and treatment follow the rhythm algorithm. RCUK adult tachyarrhythmia algorithm, March 2026: https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf For stable AF, tailor rate control to ventricular function. If LVEF is below 40%, consider a beta-blocker or digoxin. For regular broad-complex presumed VT, use the synchronised cardioversion pathway. When sedation or anaesthesia is high risk, consider procainamide, or amiodarone if procainamide is contraindicated or unavailable. Seek expert advice. Throughout, I prioritize correcting underlying ICU triggers such as electrolyte imbalances (K+ >4.0, Mg2+ >1.0), hypoxia, hypercarbia, or sympathetic surge.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines","https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]},{"path":["high_yield_points","4"],"before":"Vagal manoeuvres and Adenosine (6mg-12mg-12mg) for SVT","after":"Stable regular narrow-complex tachycardia without pre-excitation: vagal manoeuvres, then rapid IV adenosine 6 mg, 12 mg and 18 mg as indicated (RCUK March 2026).","sources":["https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]},{"path":["high_yield_points","2"],"before":"Standard ALS/RCUK synchronised DC cardioversion energy levels (120-150J)","after":"Synchronised energy is rhythm-specific: maximum output is reasonable for AF, 120–150 J initially for VT with a pulse, 70–120 J initially for flutter or paroxysmal SVT.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]}]},{"table":"viva_model_answers","id":"2ae3bbfd-ace7-49de-8092-5e666c730ad8","guard":{},"edits":[{"path":["model_answer"],"before":"The management of bradycardia in the ICU follows the Resuscitation Council UK (RCUK) peri-arrest algorithm. The initial step is to assess for 'adverse features', which include shock (hypotension, CRT >2s), syncope, myocardial ischemia, or acute heart failure.\n\nIf adverse features are present, the first-line pharmacological intervention is Atropine 500 mcg IV, repeatable every 3-5 minutes to a maximum of 3 mg (RCUK 2021 adult bradycardia algorithm). If Atropine is ineffective or if there is a high risk of asystole (e.g., Mobitz II or complete heart block with wide QRS), second-line measures must be initiated. These include infusions of Isoprenaline (starting at 5mcg/min) or Adrenaline (2-10mcg/min), or transcutaneous pacing (TCP). \n\nWhen using TCP, it is vital to ensure both electrical capture (a pacer spike followed by a QRS) and mechanical capture (a palpable pulse that correlates with the pacer rate, typically checked at the right femoral artery to avoid confusion with muscle twitching). I would ensure the patient is appropriately sedated or receives analgesia, as TCP is painful. If these measures are required, I would advocate for the insertion of a temporary transvenous cardiac pacemaker (TVP). Temporary pacing is indicated for symptomatic bradycardia refractory to medical therapy or for prophylaxis in high-risk blocks (e.g., new bifascicular block with anterior MI). Current usually starts at 5-10mA for capture, and the 'sensitvity' should be set to avoid R-on-T phenomena.","after":"The management of bradycardia in the ICU follows the Resuscitation Council UK (RCUK) peri-arrest algorithm. The initial step is to assess for 'adverse features', which include shock (hypotension, CRT >2s), syncope, myocardial ischemia, or acute heart failure.\n\nIn adult bradycardia with adverse signs, give atropine 500 micrograms IV when appropriate, repeating at 3–5 minute intervals to a maximum of 3 mg. Avoid atropine in high-degree AV block with a wide QRS because it can worsen the block. Avoid it after cardiac transplantation because it can precipitate high-grade block or sinus arrest. Seek expert help and arrange early pacing where indicated. Isoprenaline or adrenaline infusion can support haemodynamics while arranging pacing. RCUK also advises considering aminophylline in the transplanted heart. Source: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines \n\nWhen using TCP, it is vital to ensure both electrical capture (a pacer spike followed by a QRS) and mechanical capture (a palpable pulse that correlates with the pacer rate, typically checked at the right femoral artery to avoid confusion with muscle twitching). I would ensure the patient is appropriately sedated or receives analgesia, as TCP is painful. If these measures are required, I would advocate for the insertion of a temporary transvenous cardiac pacemaker (TVP). Temporary pacing is indicated for symptomatic bradycardia refractory to medical therapy or for prophylaxis in high-risk blocks (e.g., new bifascicular block with anterior MI). Current usually starts at 5-10mA for capture, and the 'sensitvity' should be set to avoid R-on-T phenomena.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]},{"path":["high_yield_points","1"],"before":"Standard Atropine dose: 500mcg IV (repeating up to 3mg).","after":"Atropine 500 micrograms IV, up to 3 mg cumulatively when indicated. Avoid in high-degree AV block with wide QRS and after cardiac transplant.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]},{"path":["pitfalls","2"],"before":"Giving Atropine to a post-cardiac transplant patient (it is ineffective due to denervation).","after":"Giving atropine after heart transplant can precipitate high-degree AV block or sinus arrest.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]},{"path":["high_yield_points","4"],"before":"Indications for transvenous pacing: Asystole, Mobitz II, 3rd-degree block with adverse features.","after":"Arrange early pacing for unstable, symptomatic bradycardia or high-risk block. Differentiate true asystole from ventricular standstill with visible P waves when considering pacing.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]}]},{"table":"viva_model_answers","id":"2cf2f73b-5fdf-4c9c-b198-1f54d8992c72","guard":{},"edits":[{"path":["model_answer"],"before":"Antiarrhythmic drugs are substances used to suppress or prevent cardiac rhythm disturbances by altering the electrophysiological properties of the myocardium. The most widely used framework is the Vaughan-Williams classification, which categorizes agents into four main classes based on their primary mechanism of action.\n\nClass I agents are Sodium-channel blockers, further divided by their kinetics: Ia (e.g., Procainamide) prolongs the action potential, Ib (e.g., Lidocaine) shortens it, and Ic (e.g., Flecainide) has no effect on duration but significantly slows conduction. Class II are beta-adrenoceptor antagonists, which reduce sympathetic drive. Class III agents, such as Amiodarone or Sotalol, primarily block Potassium channels to prolong the refractory period. Class IV are Calcium-channel blockers (Verapamil/Diltiazem).\n\nAmiodarone is a particularly high-yield Class III agent. Although primarily a K-channel blocker, it exhibits properties of all four classes. It has a massive volume of distribution (approx. 70 L/kg) due to high lipid solubility and an exceptionally long elimination half-life of 20 to 100 days. It contains iodine, which contributes to its side-effect profile, including thyroid dysfunction (hypo/hyper), pulmonary fibrosis, and corneal deposits.\n\nIn the acute setting, Adenosine is used for supraventricular tachycardia (SVT). It acts on A1 receptors in the AV node, opening K+ channels and inhibiting Ca2+ influx via a Gi-protein pathway, causing transient heart block. It has a half-life of less than 10 seconds due to rapid uptake by erythrocytes and vascular endothelial cells. The standard dose is 6mg, 12mg, then 12mg via a large-bore cannula in a central vein or the antecubital fossa.","after":"Antiarrhythmic drugs are substances used to suppress or prevent cardiac rhythm disturbances by altering the electrophysiological properties of the myocardium. The most widely used framework is the Vaughan-Williams classification, which categorizes agents into four main classes based on their primary mechanism of action.\n\nClass I agents are Sodium-channel blockers, further divided by their kinetics: Ia (e.g., Procainamide) prolongs the action potential, Ib (e.g., Lidocaine) shortens it, and Ic (e.g., Flecainide) has no effect on duration but significantly slows conduction. Class II are beta-adrenoceptor antagonists, which reduce sympathetic drive. Class III agents, such as Amiodarone or Sotalol, primarily block Potassium channels to prolong the refractory period. Class IV are Calcium-channel blockers (Verapamil/Diltiazem).\n\nAmiodarone is a particularly high-yield Class III agent. Although primarily a K-channel blocker, it exhibits properties of all four classes. It has a massive volume of distribution (approx. 70 L/kg) due to high lipid solubility and an exceptionally long elimination half-life of 20 to 100 days. It contains iodine, which contributes to its side-effect profile, including thyroid dysfunction (hypo/hyper), pulmonary fibrosis, and corneal deposits.\n\nIn the acute setting, Adenosine is used for supraventricular tachycardia (SVT). It acts on A1 receptors in the AV node, opening K+ channels and inhibiting Ca2+ influx via a Gi-protein pathway, causing transient heart block. It has a half-life of less than 10 seconds due to rapid uptake by erythrocytes and vascular endothelial cells. For an adult with stable regular narrow-complex tachycardia persisting after vagal manoeuvres, with no pre-excitation or other contraindication, the RCUK algorithm uses adenosine 6 mg as a rapid IV bolus followed by a flush. If unsuccessful, give 12 mg, then 18 mg if needed. Further assessment and treatment follow the rhythm algorithm. RCUK adult tachyarrhythmia algorithm, March 2026: https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf","sources":["https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]}]},{"table":"viva_model_answers","id":"321fe4a1-740a-412c-bcc4-8b50890ba9c8","guard":{},"edits":[{"path":["model_answer"],"before":"Post-ROSC care is the critical physiological optimization required to mitigate the 'Post-Cardiac Arrest Syndrome,' which comprises brain injury, myocardial dysfunction, systemic ischaemia-reperfusion response, and the persistent precipitating pathology. \n\nManagement is structured into immediate, intermediate, and long-term phases. Following ROSC, stabilization focuses on airway protection and oxygenation, titrating FiO2 to target an arterial oxygen saturation (SpO2) of 94-98% (PaO2 10-13 kPa), avoiding both hypoxia and hyperoxia as per ERC/ESICM 2021. Hyperoxaemia should be avoided as it exacerbates oxidative stress. Ventilation should aim for normocapnia (4.5-6.0 kPa) to prevent fluctuations in cerebral blood flow.\n\nHaemodynamically, the goal is to maintain a MAP between 65-80 mmHg. Early echocardiography is vital to assess for myocardial stunning, which may require inotropic support or an IABP/Impella. If an ST-elevation MI is present, or there is high suspicion of a coronary occlusion, immediate coronary angiography is indicated.\n\nTemperature management has shifted following the TTM2 trial. Current ERC/ESICM guidelines suggest maintaining a core temperature of ≤37.5°C. Active cooling is no longer mandatory for all, but fever (>37.7°C) must be aggressively prevented for at least 72 hours using antipyretics or cooling devices. Continuous EEG monitoring is ideal to detect non-convulsive status epilepticus. Sedation should be minimized where possible to facilitate early neurological assessment, though short-acting agents like propofol and remifentanil are preferred to allow for rapid clearance.","after":"Post-ROSC care is the critical physiological optimization required to mitigate the 'Post-Cardiac Arrest Syndrome,' which comprises brain injury, myocardial dysfunction, systemic ischaemia-reperfusion response, and the persistent precipitating pathology. \n\nManagement is structured into immediate, intermediate, and long-term phases. Following ROSC, stabilization focuses on airway protection and oxygenation, titrating FiO2 to target an arterial oxygen saturation (SpO2) of 94-98% (PaO2 10-13 kPa), avoiding both hypoxia and hyperoxia as per ERC/ESICM 2021. Hyperoxaemia should be avoided as it exacerbates oxidative stress. Ventilation should aim for normocapnia (4.7–6.0 kPa) to prevent fluctuations in cerebral blood flow.\n\nHaemodynamically, the goal is to maintain a MAP between 65-80 mmHg. Early echocardiography is vital to assess for myocardial stunning, which may require inotropic support or an IABP/Impella. If an ST-elevation MI is present, or there is high suspicion of a coronary occlusion, immediate coronary angiography is indicated.\n\nTemperature management has shifted following the TTM2 trial. Current ERC/ESICM guidelines suggest maintaining a core temperature of ≤37.5°C. Actively prevent fever while coma persists, using temperature-control measures as needed. RCUK full-text guidance specifies 36–72 hours. RCUK post-resuscitation guidance: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines Continuous EEG monitoring is ideal to detect non-convulsive status epilepticus. Sedation should be minimized where possible to facilitate early neurological assessment, though short-acting agents like propofol and remifentanil are preferred to allow for rapid clearance.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]},{"path":["high_yield_points","0"],"before":"Aggressive treatment of seizure/myoclonus (non-sedating)","after":"Use EEG to assess seizures and myoclonus. Treat clinical or electrographic seizures and check for compatible EEG activity when myoclonus is present.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]},{"path":["high_yield_points","1"],"before":"Normoxemia (PaO2 10-13 kPa) and Normocapnia (PaCO2 4.5-6.0 kPa)","after":"Target SpO₂ 94–98% once reliable, PaO₂ 10–13 kPa and PaCO₂ 4.7–6.0 kPa.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]},{"path":["high_yield_points","2"],"before":"Avoidance of hyperthermia (>37.7°C) for 72 hours (TTM2 data)","after":"In patients who remain comatose after ROSC, actively prevent fever and target core temperature ≤37.5°C.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]},{"path":["high_yield_points","4"],"before":"Early PCI/Coronary angiography if STEMI or suspected cardiac cause","after":"Prioritise coronary angiography for persistent ST elevation or a high likelihood of coronary occlusion. Perform PCI if indicated.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]}]},{"table":"viva_model_answers","id":"47d1b501-60f5-4372-ae38-015ff40df728","guard":{},"edits":[{"path":["model_answer"],"before":"Adenosine is a naturally occurring endogenous purine nucleoside used primarily for the rapid termination of paroxysmal supraventricular tachycardias (pSVT) involving the AV node. \n\nIts mechanism involves binding to the G-protein coupled A1 receptors in the AV node. This activation inhibits adenylate cyclase, reducing cAMP, and leads to the activation of T-type potassium channels. The resulting potassium efflux hyperpolarises the nodal cell membrane and inhibits slow inward calcium currents. This significantly increases the refractory period of the AV node, effectively 'breaking' the re-entry circuit.\n\nClinically, adenosine is administered as a rapid intravenous bolus via a large-bore cannula in a proximal vein, followed by a saline flush. The initial dose is typically 6mg, followed by 12mg and a further 12mg if required. It has an exceptionally short half-life of less than 10 seconds due to rapid uptake into erythrocytes and endothelial cells, where it is metabolised to inosine and adenosine monophosphate.\n\nCommon side effects include a transient feeling of 'impending doom,' chest tightness, and dyspnoea. It is contraindicated in patients with second or third-degree heart block (without a pacemaker) and should be used with extreme caution in asthmatics due to potential bronchospasm via A2/A3 receptors. Notably, the dose must be reduced in patients on dipyridamole or central lines, and increased in patients taking theophylline or caffeine, which act as competitive antagonists.","after":"Adenosine is a naturally occurring endogenous purine nucleoside used primarily for the rapid termination of paroxysmal supraventricular tachycardias (pSVT) involving the AV node. \n\nIts mechanism involves binding to the G-protein coupled A1 receptors in the AV node. This activation inhibits adenylate cyclase, reducing cAMP, and leads to the activation of T-type potassium channels. The resulting potassium efflux hyperpolarises the nodal cell membrane and inhibits slow inward calcium currents. This significantly increases the refractory period of the AV node, effectively 'breaking' the re-entry circuit.\n\nClinically, adenosine is administered as a rapid intravenous bolus via a large-bore cannula in a proximal vein, followed by a saline flush. For an adult with stable regular narrow-complex tachycardia persisting after vagal manoeuvres, with no pre-excitation or other contraindication, the RCUK algorithm uses adenosine 6 mg as a rapid IV bolus followed by a flush. If unsuccessful, give 12 mg, then 18 mg if needed. Further assessment and treatment follow the rhythm algorithm. RCUK adult tachyarrhythmia algorithm, March 2026: https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf It has an exceptionally short half-life of less than 10 seconds due to rapid uptake into erythrocytes and endothelial cells, where it is metabolised to inosine and adenosine monophosphate.\n\nCommon side effects include a transient feeling of 'impending doom,' chest tightness, and dyspnoea. It is contraindicated in patients with second or third-degree heart block (without a pacemaker) and should be used with extreme caution in asthmatics due to potential bronchospasm via A2/A3 receptors. Dipyridamole markedly potentiates adenosine; avoid concomitant use where possible. Central administration and cardiac transplantation can increase sensitivity. Theophylline and caffeine can blunt the response. Individualise dosing with specialist advice and the relevant product guidance.","sources":["https://www.medicines.org.uk/emc/medicine/25016/spc","https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]}]},{"table":"viva_model_answers","id":"645e17f8-2bc7-45a7-87c7-bd6f5e7f7d82","guard":{},"edits":[{"path":["model_answer"],"before":"Post-Resuscitation Care is the multi-disciplinary management of the 'post-cardiac arrest syndrome', characterized by myocardial dysfunction, systemic inflammatory response, and brain injury. Following Return of Spontaneous Circulation (ROSC), initial management follows the post-ROSC bundle: ABCDE stabilization with a target MAP of 65-80 mmHg, SpO2 94-98% (avoiding hyperoxia), and PaCO2 4.5-6.0 kPa.\n\nRegarding Targeted Temperature Management (TTM), the TTM2 trial has shifted practice from active cooling (33°C) to maintaining normothermia. We now focus on the avoidance of fever (target temperature ≤37.7°C) for at least 72 hours. This is typically achieved with stepped intervention: paracetamol, exposure, and, if required, surface or intravascular cooling devices.\n\nNeuroprognostication must be multimodal and delayed until at least 72 hours post-arrest to avoid interference from sedative drugs or metabolic derangement. Clinical examination focuses on the GCS-M score and pupillary/corneal reflexes. If these are absent at 72h, we use adjunctive tests:\n1. Neurophysiology: SSEP (bilateral absence of N20 waves is a high-specificity indicator of poor outcome) and EEG (presence of burst suppression or status epilepticus).\n2. Biomarkers: Neuron-Specific Enolase (NSE) > 60 µg/L at 48-72 hours. \n3. Imaging: MRI (DWI sequence) showing diffuse cortical or deep grey matter restriction.\n\nWithdrawal of Life-Sustaining Treatment (WLST) is only considered when at least two indicators of poor prognosis are present after 72 hours. If WLST is indicated, early discussion with the transplant team regarding Donation after Circulatory Death (DCD) is mandatory.","after":"Post-Resuscitation Care is the multi-disciplinary management of the 'post-cardiac arrest syndrome', characterized by myocardial dysfunction, systemic inflammatory response, and brain injury. Following Return of Spontaneous Circulation (ROSC), initial management follows the post-ROSC bundle: ABCDE stabilization with a target MAP of 65-80 mmHg, SpO2 94-98% (avoiding hyperoxia), and PaCO2 4.7–6.0 kPa.\n\nRegarding Targeted Temperature Management (TTM), the TTM2 trial has shifted practice from active cooling (33°C) to maintaining normothermia. In patients who remain comatose, actively prevent fever with a core target of ≤37.5°C. RCUK full-text guidance specifies 36–72 hours. Source: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines This is typically achieved with stepped intervention: paracetamol, exposure, and, if required, surface or intravascular cooling devices.\n\nNeuroprognostication must be multimodal and delayed until at least 72 hours post-arrest to avoid interference from sedative drugs or metabolic derangement. Clinical examination focuses on the GCS-M score and pupillary/corneal reflexes. In an unconscious patient with a motor score ≤5 at 72 hours or later, integrate timed predictors once major confounders have been excluded. Preserved brainstem reflexes do not preclude assessment with other modalities:\n1. Neurophysiology: SSEP (bilateral absence of N20 waves is a high-specificity indicator of poor outcome) and EEG (presence of burst suppression or status epilepticus).\n2. Biomarkers: Neuron-Specific Enolase (NSE) > 60 µg/L at 48-72 hours. \n3. Imaging: MRI (DWI sequence) showing diffuse cortical or deep grey matter restriction.\n\nAt least two concordant unfavourable predictors in the specified context make a poor neurological outcome very likely. Decisions about life-sustaining treatment are separate and also take into account the patient’s wishes, comorbidity, other organ failure and overall prognosis. Source: https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf If WLST is indicated, early discussion with the transplant team regarding Donation after Circulatory Death (DCD) is mandatory.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines","https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf"]},{"path":["high_yield_points","0"],"before":"TTM2: Avoidance of fever (>37.7°C) instead of active cooling.","after":"Actively prevent fever, with a core target ≤37.5°C while coma persists.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]}]},{"table":"viva_model_answers","id":"660cdfe3-f622-4066-a0e3-a492d8c75508","guard":{},"edits":[{"path":["model_answer"],"before":"Catecholamines are a group of sympathomimetic amines consisting of a benzene ring with two adjacent hydroxyl groups (a catechol nucleus) and a side-chain amine. They can be classified as endogenous (Adrenaline, Noradrenaline, Dopamine) or synthetic (Isoprenaline, Dobutamine).\n\nTheir mechanism of action involves binding to G-protein coupled adrenoceptors. Noradrenaline is a potent alpha-1 agonist with modest beta-1 activity, primarily increasing systemic vascular resistance (SVR) and mean arterial pressure (MAP). Adrenaline acts on alpha-1, beta-1, and beta-2 receptors; at low doses (0.01-0.05 mcg/kg/min), beta-effects predominate (increased heart rate, contractility, and bronchodilation), whereas higher doses increase alpha-mediated vasoconstriction. \n\nClinical relevance is found in the management of shock states. Noradrenaline is the first-line vasopressor in septic shock to maintain organ perfusion pressure. Adrenaline is the gold standard in anaphylaxis and cardiac arrest (1mg IV every 3-5 mins). Dobutamine, a synthetic catecholamine with strong beta-1 and moderate beta-2 activity, is used as an 'inodilator' in cardiogenic shock to increase cardiac output while reducing afterload.\n\nCrucially, catecholamines have a short half-life (1-2 minutes) due to rapid metabolism by Catechol-O-methyltransferase (COMT) and Monoamine oxidase (MAO), necessitating continuous intravenous infusion. Side effects include tachyarrhythmias, myocardial ischaemia, and peripheral digital ischaemia if extravasation occurs.","after":"Catecholamines are a group of sympathomimetic amines consisting of a benzene ring with two adjacent hydroxyl groups (a catechol nucleus) and a side-chain amine. They can be classified as endogenous (Adrenaline, Noradrenaline, Dopamine) or synthetic (Isoprenaline, Dobutamine).\n\nTheir mechanism of action involves binding to G-protein coupled adrenoceptors. Noradrenaline is a potent alpha-1 agonist with modest beta-1 activity, primarily increasing systemic vascular resistance (SVR) and mean arterial pressure (MAP). Adrenaline acts on alpha-1, beta-1, and beta-2 receptors; at low doses (0.01-0.05 mcg/kg/min), beta-effects predominate (increased heart rate, contractility, and bronchodilation), whereas higher doses increase alpha-mediated vasoconstriction. \n\nClinical relevance is found in the management of shock states. Noradrenaline is the first-line vasopressor in septic shock to maintain organ perfusion pressure. In adult anaphylaxis with a circulation, the general emergency regimen starts with adrenaline 500 micrograms IM, repeated after 5 minutes if needed. In monitored perioperative anaphylaxis, an experienced anaesthetist/intensivist starts with 50 micrograms IV if IV access is available. In established adult cardiac arrest, standard ALS uses 1 mg IV/IO according to rhythm: as soon as possible for a non-shockable rhythm or after the third shock for a shockable rhythm, then every 3–5 minutes. RCUK perioperative algorithm: https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf ; general anaphylaxis and ALS: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines and https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines Dobutamine, a synthetic catecholamine with strong beta-1 and moderate beta-2 activity, is used as an 'inodilator' in cardiogenic shock to increase cardiac output while reducing afterload.\n\nCrucially, catecholamines have a short half-life (1-2 minutes) due to rapid metabolism by Catechol-O-methyltransferase (COMT) and Monoamine oxidase (MAO), necessitating continuous intravenous infusion. Side effects include tachyarrhythmias, myocardial ischaemia, and peripheral digital ischaemia if extravasation occurs.","sources":["https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]},{"path":["pitfalls","1"],"before":"Failing to mention the short half-life and the requirement for central venous access.","after":"Delaying urgently indicated initial vasopressor treatment solely to obtain central access. Use an appropriate peripheral protocol, monitor the site and reassess the need for central access.","sources":["https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026"]}]},{"table":"viva_model_answers","id":"8ed0ef2c-6df2-4470-9910-33fff0aa460f","guard":{},"edits":[{"path":["model_answer"],"before":"Post-cardiac arrest syndrome (PCAS) comprises systemic ischemia-reperfusion injury, post-arrest myocardial dysfunction, and brain injury. Following Return of Spontaneous Circulation (ROSC), immediate management focuses on the 'Post-ROSC Bundle.' Initial priorities are hemodynamic stabilization (MAP 65-80 mmHg) and ventilatory titration to normocapnia (PaCO2 4.5-6.0 kPa) and normoxia (SaO2 94-98%). A 12-lead ECG is mandatory; if ST-elevation is present, immediate percutaneous coronary intervention (PPCI) is required. If no clear cause is found, early CT Brain/Pulmonary Angiogram is indicated.\n\nTemperature management has shifted following the TTM2 trial. The current standard is active prevention of fever, maintaining a core temperature ≤37.7°C for at least 72 hours, rather than traditional therapeutic hypothermia (33°C), as no survival benefit was demonstrated for the latter in unselected cohorts.\n\nNeuroprognostication is the most critical ICU phase. It must be multimodal and never performed before 72 hours post-ROSC, following the clearance of sedative drugs. In patients with a GCS-M ≤3 at 72 hours, we use:\n1. Clinical: Absent pupillary/corneal reflexes.\n2. Electrophysiology: Bilateral absence of SSEP N20 peaks or highly malignant EEG patterns (burst suppression).\n3. Biomarkers: Neuron Specific Enolase (NSE) >60 µg/L at 48-72 hours.\n4. Imaging: Diffuse edema or grey-white matter ratio blunting on CT/MRI.\n\nWithdrawal of Life Sustaining Treatment (WLST) should only be considered after this multimodal assessment, ensuring family involvement and consideration of organ donation where appropriate.","after":"Post-cardiac arrest syndrome (PCAS) comprises systemic ischemia-reperfusion injury, post-arrest myocardial dysfunction, and brain injury. Following Return of Spontaneous Circulation (ROSC), immediate management focuses on the 'Post-ROSC Bundle.' Initial priorities are hemodynamic stabilization (MAP 65-80 mmHg) and ventilatory titration to normocapnia (PaCO2 4.7–6.0 kPa) and normoxia (SaO2 94-98%). A 12-lead ECG is mandatory; in suspected cardiac arrest of coronary origin with persistent ST elevation, prioritise emergency coronary angiography and perform PCI if indicated. Without ST elevation, consider immediate angiography when there is high clinical suspicion of acute coronary occlusion. If no clear cause is found, early CT Brain/Pulmonary Angiogram is indicated.\n\nTemperature management has shifted following the TTM2 trial. In patients who remain comatose, actively prevent fever with a core target ≤37.5°C. RCUK full-text guidance specifies 36–72 hours. Source: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines\n\nNeuroprognostication is the most critical ICU phase. Collect examinations, EEG and other evidence at the appropriate times, beginning earlier where indicated. Integrate findings for formal prognosis in an unconscious patient with a motor score ≤5 at 72 hours or later after excluding confounders. Source: https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf\nUse the following modalities:\n1. Clinical: Absent pupillary/corneal reflexes.\n2. Electrophysiology: Bilateral absence of SSEP N20 peaks or highly malignant EEG patterns (burst suppression).\n3. Biomarkers: Neuron Specific Enolase (NSE) >60 µg/L at 48-72 hours.\n4. Imaging: Diffuse edema or grey-white matter ratio blunting on CT/MRI.\n\nKeep the neurological prognosis and decisions about life-sustaining treatment separate. Discuss the patient’s wishes, other organ function, comorbidities, and overall prognosis with the appropriate clinical team and family.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines","https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf"]},{"path":["high_yield_points","1"],"before":"TTM2 targets: Avoidance of fever >37.7°C (Normothermia).","after":"In patients who remain comatose, actively prevent fever and target core temperature ≤37.5°C.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/post-resuscitation-care-guidelines"]}]},{"table":"viva_model_answers","id":"98c763f7-717a-4745-8f7a-724716498c89","guard":{},"edits":[{"path":["model_answer"],"before":"Anaphylaxis is a severe, life-threatening, generalised or systemic hypersensitivity reaction. In the perioperative setting, it is most commonly IgE-mediated (Type 1 hypersensitivity), with Neuromuscular Blocking Agents (NMBAs), antibiotics (teicoplanin/penicillins), and chlorhexidine being the most frequent culprits according to the NAP6 study.\n\nThe clinical presentation is characterised by rapid onset of airway (angioedema), breathing (bronchospasm/high airway pressures), or circulation (profound hypotension/tachycardia) issues. Skin changes like urticaria or flushing are common but may be absent or hidden by surgical drapes in 20% of cases.\n\nImmediate management follows the AAGBI/Resus Council guidelines: Discontinue potential triggers, call for help, and administer 100% oxygen. Adrenaline is the cornerstone of treatment. If IV access is available, titrated doses of 50–100 mcg should be used; otherwise, 0.5 mg IM. Aggressive fluid resuscitation with crystalloids (up to 50 ml/kg) is vital to counteract the massive vasodilation and capillary leak. Refractory cases may require adrenaline infusions or glucagon if the patient is on beta-blockers.\n\nFor diagnosis confirmation, serial mast cell tryptase samples must be taken: the first as soon as possible, the second at 1-2 hours post-event, and a third 'baseline' at >24 hours (or at follow-up). Patients must be monitored for at least 6-12 hours due to the risk of biphasic reactions and referred to a specialist allergy clinic.","after":"Anaphylaxis is a severe, life-threatening, generalised or systemic hypersensitivity reaction. In the perioperative setting, it is most commonly IgE-mediated (Type 1 hypersensitivity), with Neuromuscular Blocking Agents (NMBAs), antibiotics (teicoplanin/penicillins), and chlorhexidine being the most frequent culprits according to the NAP6 study.\n\nThe clinical presentation is characterised by rapid onset of airway (angioedema), breathing (bronchospasm/high airway pressures), or circulation (profound hypotension/tachycardia) issues. Skin changes like urticaria or flushing are common but may be absent or hidden by surgical drapes in 20% of cases.\n\nImmediate management follows the AAGBI/Resus Council guidelines: Discontinue potential triggers, call for help, and administer 100% oxygen. Adrenaline is the cornerstone of treatment. For this monitored adult, give an initial 50 micrograms adrenaline IV and titrate to response. Without IV access, give 10 micrograms/kg IM, up to 500 micrograms, and establish IV/IO access. Start CPR if systolic BP falls below 50 mmHg or cardiac arrest occurs. RCUK perioperative algorithm: https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf Aggressive fluid resuscitation with crystalloids (up to 50 ml/kg) is vital to counteract the massive vasodilation and capillary leak. Refractory cases may require adrenaline infusions or glucagon if the patient is on beta-blockers.\n\nFor diagnosis confirmation, serial mast cell tryptase samples must be taken: the first as soon as possible, the second at 1-2 hours post-event, and a third 'baseline' at >24 hours (or at follow-up). Patients must be monitored for at least 6-12 hours due to the risk of biphasic reactions and referred to a specialist allergy clinic.","sources":["https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]},{"path":["high_yield_points","0"],"before":"Adrenaline 50mcg-100mcg IV (titrated) or 0.5mg IM.","after":"Adult perioperative anaphylaxis with a circulation: initial adrenaline 50 micrograms IV with expert monitoring. If no IV access, 10 micrograms/kg IM up to 500 micrograms.","sources":["https://www.resus.org.uk/sites/default/files/2024-01/2526%20AAP%20RCUK%20periop%20anaphylaxis-8C.pdf"]}]},{"table":"viva_model_answers","id":"ad662c35-ba5b-4b82-9b3f-7025b37759df","guard":{},"edits":[{"path":["model_answer"],"before":"Neuroprognostication after cardiac arrest is a process used to predict a poor neurological outcome (defined as CPC 3-5). It must be multimodal, as no single test carries a 0% false-positive rate. The process is only initiated after correcting confounders seperti residual sedation, neuromuscular blockade, or severe metabolic disturbances.\n\nThe 2021 ERC/ESICM guidelines recommend a structured algorithm at ≥72 hours post-ROSC in patients with a GCS Motor score of ≤3. \n1. **Clinical Examination**: Absent pupillary and corneal reflexes are strong predictors of poor outcome. \n2. **Electrophysiology**: Bilateral absence of the N20 peak on Somatosensory Evoked Potentials (SSEP) is a highly reliable indicator of cortical necrosis. EEG findings such as 'suppression-burst' or 'highly malignant' patterns (e.g., periodic discharges) support a poor prognosis. \n3. **Biomarkers**: Neuron-Specific Enolase (NSE) levels >60 µg/L at 48 and 72 hours correlate with extensive neuronal damage. \n4. **Imaging**: Brain CT (showing loss of grey-white matter differentiation) or MRI-DWI (showing restricted diffusion) can provide structural evidence of hypoxic-ischaemic brain injury (HIBI).\n\nIt is essential to wait for clinical stability. If results are discordant (e.g., absent reflexes but normal MRI), a period of further observation is mandated before considering withdrawal of life-sustaining treatment.","after":"Neuroprognostication after cardiac arrest is a process used to predict a poor neurological outcome (defined as CPC 3-5). It must be multimodal, as no single test carries a 0% false-positive rate. The process is only initiated after correcting confounders seperti residual sedation, neuromuscular blockade, or severe metabolic disturbances.\n\nThe RCUK 2025 algorithm applies in an unconscious patient with a GCS motor score ≤5 at 72 hours or later after ROSC, once major confounders are excluded. Source: https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf \n1. **Clinical Examination**: Absent pupillary and corneal reflexes are strong predictors of poor outcome. \n2. **Electrophysiology**: Bilateral absence of the N20 peak on Somatosensory Evoked Potentials (SSEP) is a highly reliable indicator of cortical necrosis. EEG findings such as 'suppression-burst' or 'highly malignant' patterns (e.g., periodic discharges) support a poor prognosis. \n3. **Biomarkers**: Neuron-Specific Enolase (NSE) levels >60 µg/L at 48 and 72 hours correlate with extensive neuronal damage. \n4. **Imaging**: Brain CT (showing loss of grey-white matter differentiation) or MRI-DWI (showing restricted diffusion) can provide structural evidence of hypoxic-ischaemic brain injury (HIBI).\n\nIt is essential to wait for clinical stability. If results are discordant (e.g., absent reflexes but normal MRI), a period of further observation is mandated before considering withdrawal of life-sustaining treatment.","sources":["https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf"]},{"path":["high_yield_points","2"],"before":"Clinical: GCS-M ≤3 (extensor/none) and absent pupillary/corneal reflexes","after":"Enter the prognostication algorithm for persistent unconsciousness with GCS motor score ≤5 at ≥72 hours after confounder exclusion. Bilaterally absent pupillary and corneal reflexes at ≥72 hours are one unfavourable predictor.","sources":["https://www.resus.org.uk/sites/default/files/2025-10/Adult%20neuroprognostication%202025.pdf"]}]},{"table":"viva_model_answers","id":"c78f641f-af26-4c95-9bef-610357a66cce","guard":{},"edits":[{"path":["model_answer"],"before":"Heart block refers to a delay or failure in the conduction of the electrical impulse from the atria to the ventricles. I classify it into three degrees. First-degree block is a simple delay (PR >0.20s). Second-degree is subdivided into Mobitz I (Wenckebach), where the PR interval progressively lengthens until a QRS is dropped, and Mobitz II, where the PR is constant but QRS complexes are dropped at a fixed ratio. Third-degree (complete) heart block involves total dissociation between P waves and QRS complexes.\n\nClinically, Mobitz II and 3rd-degree blocks are high-risk for asystole and require urgent intervention. In the ICU, my first-line pharmacological agent is Atropine 500 mcg IV, repeatable every 3-5 minutes to a maximum of 3 mg (RCUK 2021 adult bradycardia algorithm). If ineffective or risky (e.g., cardiac transplant), I consider Isoprenaline (5mcg/min) or Adrenaline (2-10mcg/min) infusions.\n\nIf the patient is haemodynamically unstable (BP <90 systolic, heart failure, or confusion), I would initiate immediate Transcutaneous Pacing (TCP). This requires adequate sedation (e.g., Propofol or Midazolam) as it is painful. I would set the rate to 60-70 bpm and increase current (mA) until electrical capture (wide QRS and tall T-wave) and mechanical capture (palpable pulse) are confirmed. This serves as a bridge to a temporary transvenous wire or a permanent pacemaker.","after":"Heart block refers to a delay or failure in the conduction of the electrical impulse from the atria to the ventricles. I classify it into three degrees. First-degree block is a simple delay (PR >0.20s). Second-degree is subdivided into Mobitz I (Wenckebach), where the PR interval progressively lengthens until a QRS is dropped, and Mobitz II, where the PR is constant but QRS complexes are dropped at a fixed ratio. Third-degree (complete) heart block involves total dissociation between P waves and QRS complexes.\n\nClinically, Mobitz II and 3rd-degree blocks are high-risk for asystole and require urgent intervention. In adult bradycardia with adverse signs, give atropine 500 micrograms IV when appropriate, repeating at 3–5 minute intervals to a maximum of 3 mg. Avoid atropine in high-degree AV block with a wide QRS because it can worsen the block. Avoid it after cardiac transplantation because it can precipitate high-grade block or sinus arrest. Seek expert help and arrange early pacing where indicated. Isoprenaline or adrenaline infusion can support haemodynamics while arranging pacing. RCUK also advises considering aminophylline in the transplanted heart. Source: https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines\n\nIf the patient is haemodynamically unstable (BP <90 systolic, heart failure, or confusion), I would initiate immediate Transcutaneous Pacing (TCP). This requires adequate sedation (e.g., Propofol or Midazolam) as it is painful. I would set the rate to 60-70 bpm and increase current (mA) until electrical capture (wide QRS and tall T-wave) and mechanical capture (palpable pulse) are confirmed. This serves as a bridge to a temporary transvenous wire or a permanent pacemaker.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]},{"path":["high_yield_points","3"],"before":"Atropine (500mcg increments up to 3mg) as first-line for symptomatic bradycardia","after":"Atropine 500 micrograms IV, up to 3 mg cumulatively when indicated. Avoid in high-degree AV block with wide QRS and after cardiac transplant.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]},{"path":["pitfalls","2"],"before":"Forgetting that Atropine is ineffective in heart transplant patients due to denervation.","after":"Giving atropine after heart transplant can precipitate high-degree AV block or sinus arrest.","sources":["https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/adult-advanced-life-support-guidelines"]}]},{"table":"viva_model_answers","id":"d5c02d29-fd22-4c59-be8c-13265aa0f403","guard":{},"edits":[{"path":["model_answer"],"before":"Processed EEG parameters like Spectral Edge Frequency (SEF) and the Narcotrend index provide objective measures of anaesthetic depth beyond simple dimensionless numbers. \n\nSEF95 is defined as the frequency below which 95% of the total power of the EEG spectrum is located. In an awake patient, SEF95 is high (approx. 20-30 Hz) due to beta activity. As anaesthesia deepens, there is a 'left shift' toward slower, higher-amplitude waves (delta and theta), causing the SEF95 to decrease (typically <12 Hz during maintenance). Narcotrend is a different approach, categorising the raw EEG into stages from A (awake) to F (isoelectric), subdivided into 14 sub-stages based on pattern recognition algorithms similar to sleep staging.\n\nIn terms of clinical evidence, the Cochrane review and major trials such as B-Aware and BAG-RECALL have influenced practice. The BAG-RECALL trial compared BIS-guided protocols to End-Tidal Anaesthetic Gas (ETAG) protocols, finding that in patients receiving volatile anaesthesia, ETAG monitoring was equally effective at preventing AAGA. However, the NAP5 report and current NICE guidelines (DG24) strongly recommend processed EEG monitoring (BIS, Entropy, or Narcotrend) for all patients receiving TIVA with neuromuscular blockade, as ETAG is unavailable and clinical signs are unreliable. Using these monitors has been shown to reduce anaesthetic consumption and recovery times, though their role in preventing AAGA in low-risk volatile cases remains debated.","after":"Processed EEG parameters like Spectral Edge Frequency (SEF) and the Narcotrend index provide objective measures of anaesthetic depth beyond simple dimensionless numbers. \n\nSEF95 is defined as the frequency below which 95% of the total power of the EEG spectrum is located. In an awake patient, SEF95 is high (approx. 20-30 Hz) due to beta activity. As anaesthesia deepens, there is a 'left shift' toward slower, higher-amplitude waves (delta and theta), causing the SEF95 to decrease (typically <12 Hz during maintenance). Narcotrend is a different approach, categorising the raw EEG into stages from A (awake) to F (isoelectric), subdivided into 14 sub-stages based on pattern recognition algorithms similar to sleep staging.\n\nIn terms of clinical evidence, the Cochrane review and major trials such as B-Aware and BAG-RECALL have influenced practice. In high-risk patients receiving volatile anaesthesia, BAG-RECALL did not demonstrate superiority of BIS-guided care over an end-tidal agent concentration protocol for preventing definite awareness. The study did not establish equivalence. Source: https://pubmed.ncbi.nlm.nih.gov/21848460/ The Association of Anaesthetists recommends processed EEG when TIVA is combined with neuromuscular blockade, from before induction until recovery from blockade is confirmed. NICE HTG292 lists EEG-based monitoring as an option for all TIVA and for higher-risk general anaesthesia. Sources: https://doi.org/10.1111/anae.15501 and https://www.nice.org.uk/guidance/htg292 Using these monitors has been shown to reduce anaesthetic consumption and recovery times, though their role in preventing AAGA in low-risk volatile cases remains debated.","sources":["https://doi.org/10.1111/anae.15501","https://pubmed.ncbi.nlm.nih.gov/21848460/"]},{"path":["high_yield_points","3"],"before":"B-G-A (B-type-Gamma-Aminobutyric Acid) loop changes.","after":"Interpret the processed index alongside the EEG, clinical circumstances and artefacts.","sources":["https://www.nice.org.uk/guidance/htg292"]},{"path":["high_yield_points","4"],"before":"Clinical Evidence: B-AWAKE and BAG-RECALL trials.","after":"Clinical evidence includes B-Aware and BAG-RECALL.","sources":["https://pubmed.ncbi.nlm.nih.gov/21848460/"]}]},{"table":"viva_model_answers","id":"d67fdd51-f0f9-4aa2-8119-f3801e98caa0","guard":{},"edits":[{"path":["model_answer"],"before":"The management of a difficult airway in the ICU should follow the 2018 DAS/PICS 'Intubation of the Critically Ill' guidelines. Unlike the elective setting, ICU patients have reduced physiological reserve and a high risk of cardiovascular collapse. \n\nMy approach follows a Plan A to D structure. **Plan A** is initial intubation using a maximum of three attempts (3 + 1 if a senior clinician joins). I would ensure optimal positioning, use a videolaryngoscope (VL) as first-line, and apply cricoid pressure if indicated, though I would release it if it hindered the view. I would use Rocuronium 1.2mg/kg to ensure paralysis.\n\nIf Plan A fails, **Plan B** involves maintaining oxygenation using a Supraglottic Airway Device (SAD), preferably a second-generation device. Attempts should be limited to a maximum of three. If oxygenation is successful, I would stop and think: wake the patient (rare in ICU), use the SAD as a conduit, or proceed to a surgical airway.\n\n**Plan C** is a final attempt at face-mask ventilation using two-person technique, adjuncts.\n\nIf oxygenation is impossible, I would declare **Plan D**: CICO. The technique of choice is a Scalpel-Bougie-Tube approach: a transverse incision through the cricothyroid membrane, insertion of a coudé-tipped bougie, and threading a size 6.0mm cuffed ETT. Key figures include a 100% requirement for waveform capnography and the acknowledgement that over 10% of ICU intubations involve a 'difficult' airway.","after":"The management of a difficult airway in the ICU should follow the 2018 DAS/PICS 'Intubation of the Critically Ill' guidelines. Unlike the elective setting, ICU patients have reduced physiological reserve and a high risk of cardiovascular collapse. \n\nMy approach follows a Plan A to D structure. **Plan A** is initial intubation using a maximum of three attempts (3 + 1 if a senior clinician joins). I would ensure optimal positioning, use a videolaryngoscope (VL) as first-line, and apply cricoid pressure if indicated, though I would release it if it hindered the view. I would use Rocuronium 1.2mg/kg to ensure paralysis.\n\nIf Plan A fails, **Plan B** involves maintaining oxygenation using a Supraglottic Airway Device (SAD), preferably a second-generation device. Attempts should be limited to a maximum of three. If oxygenation is successful, I would stop and think: wake the patient (rare in ICU), use the SAD as a conduit, or proceed to a surgical airway.\n\n**Plan C** is a final attempt at face-mask ventilation using two-person technique, adjuncts.\n\nIf oxygenation is impossible, I would declare **Plan D**: CICO. Use the trained scalpel–bougie–tube technique. When membrane palpability is uncertain or has not been assessed, default to a vertical midline skin incision, identify and stabilise the larynx and membrane, then open the membrane transversely, pass the bougie and railroad a size 6.0 cuffed tracheal tube. Source: https://doi.org/10.1016/j.bja.2025.10.006 Key figures include a 100% requirement for waveform capnography and the acknowledgement that over 10% of ICU intubations involve a 'difficult' airway.","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"viva_model_answers","id":"db8aa09e-7fc9-4135-8c6c-52d97ab98905","guard":{},"edits":[{"path":["model_answer"],"before":"Emergency Front of Neck Access (eFONA) is the final step (Plan D) in the DAS guidelines, indicated when both intubation and oxygenation via SAD or facemask have failed (CICO). The preferred method is the Scalpel-Bougie-Tube (SBT) technique due to its superior reliability and speed compared to cannula-based techniques.\n\nThe procedure begins with the patient's neck in full extension. The cricothyroid membrane (CTM) is identified via palpation or the 'laryngeal handshake'. If the CTM is impalpable (e.g., in obesity), a midline vertical incision is made to facilitate identification. Once identified, a horizontal incision is made through the skin and CTM. The scalpel blade is turned 90 degrees to open the space, and a coudé-tipped bougie is passed into the trachea. A size 6.0 mm cuffed endotracheal tube is then railroaded over the bougie, the cuff is inflated, and ventilation is confirmed with capnography.\n\nClinically, this is a high-stress, low-frequency event. The success of the procedure relies on 'declaring' the CICO state early to avoid profound hypoxia. Pitfalls include failing to extend the neck and Losing the midline. The key metric is the 'laryngeal hand'—using the non-dominant hand to stabilize the thyroid cartilage throughout. Confirmation of tube placement must be physiological (CO2) rather than visual alone.","after":"Emergency Front of Neck Access (eFONA) is the final step (Plan D) in the DAS guidelines, indicated when both intubation and oxygenation via SAD or facemask have failed (CICO). The preferred method is the Scalpel-Bougie-Tube (SBT) technique due to its superior reliability and speed compared to cannula-based techniques.\n\nThe procedure begins with the patient's neck in full extension. The cricothyroid membrane (CTM) is identified via palpation or the 'laryngeal handshake'. DAS 2025 defaults to a midline vertical skin incision if palpability has not been assessed or is uncertain. Identify and stabilise the larynx and membrane, then make the transverse membrane incision. A transverse skin approach requires reliable identification of the membrane. Source: https://doi.org/10.1016/j.bja.2025.10.006 The scalpel blade is turned 90 degrees to open the space, and a coudé-tipped bougie is passed into the trachea. A size 6.0 mm cuffed endotracheal tube is then railroaded over the bougie, the cuff is inflated, and ventilation is confirmed with capnography.\n\nClinically, this is a high-stress, low-frequency event. The success of the procedure relies on 'declaring' the CICO state early to avoid profound hypoxia. Pitfalls include failing to extend the neck and Losing the midline. The key metric is the 'laryngeal hand'—using the non-dominant hand to stabilize the thyroid cartilage throughout. Confirmation of tube placement must be physiological (CO2) rather than visual alone.","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["high_yield_points","3"],"before":"Horizontal incision, 90-degree rotation of the blade","after":"Distinguish the initial vertical midline skin incision in the default approach from the subsequent transverse membrane incision.","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]},{"path":["pitfalls","2"],"before":"Neglecting to mention the 'impalpable' CTM pathway (vertical incision).","after":"Omitting the vertical skin approach when the membrane is impalpable, unassessed or uncertain.","sources":["https://doi.org/10.1016/j.bja.2025.10.006"]}]},{"table":"viva_model_answers","id":"e9eba6d4-fbb0-4793-b8d9-1297d125cd3c","guard":{},"edits":[{"path":["model_answer"],"before":"Adenosine is an endogenous purine nucleoside used primarily for the rapid termination of paroxysmal supraventricular tachycardias (SVT) involving the AV node. \n\nIts mechanism involves binding to G-protein-coupled A1 receptors in the SA and AV nodes. This leads to the inhibition of adenylyl cyclase, decreasing intracellular cAMP. More significantly, it activates inward-rectifying potassium channels (K(Ado)), causing hyperpolarization of the nodal cell membrane. It also inhibits Calcium influx, which together slows the rate of sinus fire and increases the AV nodal refractory period.\n\nPharmacokinetically, adenosine has an extremely short half-life of less than 10 seconds. This is due to rapid uptake into erythrocytes and vascular endothelial cells via the nucleoside transporter, where it is metabolized by adenosine deaminase. Consequently, it must be administered as a rapid bolus through a large-bore proximal cannula, followed by a flush.\n\nClinically, the starting dose is usually 6mg, followed by 12mg and a further 12mg if unsuccessful. It is contraindicated in asthmatics (can cause bronchospasm via A2/A3 receptors) and in patients with second or third-degree heart block. It is also potentiated by dipyridamole and antagonized by methylxanthines like caffeine and theophylline. Notably, denervated hearts (transplants) are hypersensitive to adenosine.","after":"Adenosine is an endogenous purine nucleoside used primarily for the rapid termination of paroxysmal supraventricular tachycardias (SVT) involving the AV node. \n\nIts mechanism involves binding to G-protein-coupled A1 receptors in the SA and AV nodes. This leads to the inhibition of adenylyl cyclase, decreasing intracellular cAMP. More significantly, it activates inward-rectifying potassium channels (K(Ado)), causing hyperpolarization of the nodal cell membrane. It also inhibits Calcium influx, which together slows the rate of sinus fire and increases the AV nodal refractory period.\n\nPharmacokinetically, adenosine has an extremely short half-life of less than 10 seconds. This is due to rapid uptake into erythrocytes and vascular endothelial cells via the nucleoside transporter, where it is metabolized by adenosine deaminase. Consequently, it must be administered as a rapid bolus through a large-bore proximal cannula, followed by a flush.\n\nFor an adult with stable regular narrow-complex tachycardia persisting after vagal manoeuvres, with no pre-excitation or other contraindication, the RCUK algorithm uses adenosine 6 mg as a rapid IV bolus followed by a flush. If unsuccessful, give 12 mg, then 18 mg if needed. Further assessment and treatment follow the rhythm algorithm. RCUK adult tachyarrhythmia algorithm, March 2026: https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf It is contraindicated in asthmatics (can cause bronchospasm via A2/A3 receptors) and in patients with second or third-degree heart block. It is also potentiated by dipyridamole and antagonized by methylxanthines like caffeine and theophylline. Notably, denervated hearts (transplants) are hypersensitive to adenosine.","sources":["https://www.resus.org.uk/sites/default/files/2026-03/Adult%20tachyarrhythmia%20algorithm%20V3%20March%202026.pdf"]},{"path":["high_yield_points","4"],"before":"Contraindicated in asthma and heart transplant","after":"Bronchospastic disease is a contraindication. Transplant recipients may be highly sensitive; specialist guidance supports cautious reduced dosing for an appropriate rhythm.","sources":["https://www.ishlt.org/docs/default-source/standards-guidelines/2022_guideline_ishlt_careofhtxrecipients.pdf"]}]}]$data_08c56b4e8251$::jsonb) LOOP
        IF spec->>'table' NOT IN ('drugs','podcasts','viva_model_answers') THEN
            RAISE EXCEPTION 'Unexpected table';
        END IF;
        locator := format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1',spec->>'table');
        EXECUTE locator || ' FOR UPDATE' INTO STRICT original USING (spec->>'id')::uuid;
        IF spec->>'table' = 'podcasts' THEN
            IF jsonb_build_object('topic_id',original->'topic_id','script_md5',md5(original->>'script'),
                  'audio_path_md5',md5(original->>'audio_path'),'regenerating',original->'regenerating') IS DISTINCT FROM spec->'guard' THEN
                RAISE EXCEPTION 'Stale recording, asset, topic or generation state: %',spec->>'id';
            END IF;
        ELSIF NOT (original @> (spec->'guard')) THEN
            RAISE EXCEPTION 'Row identity changed: %',spec->>'id';
        END IF;
        proposed := original;
        old_matches := true;
        new_matches := true;
        FOR item IN SELECT value FROM jsonb_array_elements(spec->'edits') LOOP
            target := ARRAY(SELECT jsonb_array_elements_text(item->'path'));
            old_matches := old_matches AND ((original #> target) IS NOT DISTINCT FROM (item->'before'));
            new_matches := new_matches AND ((original #> target) IS NOT DISTINCT FROM (item->'after'));
            proposed := jsonb_set(proposed, target, item->'after', false);
        END LOOP;
        
        IF new_matches THEN CONTINUE; END IF;
        IF NOT old_matches THEN
            RAISE EXCEPTION 'Stale, missing or partially changed audited values: %.%',spec->>'table',spec->>'id';
        END IF;
        SELECT string_agg(format('%1$I = (jsonb_populate_record(NULL::public.%2$I,$1)).%1$I',field,spec->>'table'), ', ' ORDER BY field)
          INTO assignments FROM (SELECT DISTINCT e->'path'->>0 AS field FROM jsonb_array_elements(spec->'edits') e) columns_to_change;
        EXECUTE format('UPDATE public.%I SET %s WHERE id=$2',spec->>'table',assignments)
          USING proposed, (spec->>'id')::uuid;
        GET DIAGNOSTICS affected = ROW_COUNT;
        IF affected <> 1 THEN RAISE EXCEPTION 'Expected to update one row: %',spec->>'id'; END IF;
        EXECUTE locator INTO STRICT reread USING (spec->>'id')::uuid;
        FOR item IN SELECT value FROM jsonb_array_elements(spec->'edits') LOOP
            target := ARRAY(SELECT jsonb_array_elements_text(item->'path'));
            IF (reread #> target) IS DISTINCT FROM (item->'after') THEN
                RAISE EXCEPTION 'Read-back failed: % %',spec->>'id',target;
            END IF;
        END LOOP;
    END LOOP;
END;
$audit_08c56b4e8251$;
